   "content": "【术数全书·下册·丙丁龟鉴·第7/12节】（公有领域原典·宋柴望辑·杂占·Vision OCR）\n\n之朝廷。今疆场日蹙，疆，纪良反，界也。场，益羊反，畔也。隋军\n压境，陛下如不改弦易张，臣见麋鹿复游于姑苏矣。”帝大怒，\n即日斩之。\n臣望谨按：祯明三年，隋遂灭陈。则至德丙午，祯明丁未，\n岂非陈之厄岁乎？虽然陈以是年为厄岁，隋以是年为兴运。乃\n知隋不能亡陈，陈实自亡也。向若陈主因章华之谏，而反身修\n德，虽有百隋，无奈陈何！数虽逢厄，安能厄之？\n卷之四\n唐\n太宗皇帝姓李氏\n贞观二十年丙午 贞观二十一年丁未\n贞观二十年，三月乙已，上至自高丽。帝往高丽，是时达京师。\n闰月癸朔，日食。秋八月，上自诣灵州招抚，遣李世费至郁\n督军山咄摩支降江。夏王道宗兵渡碛，延陀拒战，道宗破之。驾\n至浮阳，回纥等十一姓各遣使归命，乞置官司。上纳之，置六\n都督七州以抚之。上为诗曰：“雪耻酬百王，除凶报干古。”勒石干灵州。\n九月辛亥，灵州地震。十月，贬萧瑀为商州刺史。\n贞观二十一年，诏以来年仲春，有事于泰山。以牛进达、李\n世勣为行军大总管，伐高丽。时上将复伐高丽，朝议以为高丽\n依山为城，攻之不可猝拔。前大驾亲征，国人不得耕种，大半\n乏食。今若遣偏师，更迭扰其疆场，使彼疲于奔命，释来入堡。\n数年之间，千里萧条，则人心自离，鸭绿之北，可不战而取矣。\n上从之，遣牛进达、李世勣，水陆并进以讨之。夏作翠微宫，修\n终南山太和废宫，为翠微宫。以上得风疾，苦干盛篝。立李素为燕然都\n护，统瀚海、等府六督。皋兰等七州。七月，作玉华宫，立皇子\n明为曹王。曹王明，母杨氏，巢刺王之妃也，有宠于上。发江南人造\n大船。欲复征高丽也。\n臣望谨按：五帝三皇，以仁义之兵行于天下也。太宗因盖\n苏文弑君之事，故举高丽问罪之师，宜矣。诛其贼，吊其人，置\n君而去之可也。伐之不克，不胜其忿，益欲发兵扰之，使不得\n耕种，是以暴禁暴也。吁！轮台之诏，武帝晚年"
