   "content": "【术数全书·下册·丙丁龟鉴·第12/12节】（公有领域原典·宋柴望辑·杂占·Vision OCR）\n\n重刊稽瑞序\n子思子曰：“国家将兴，必有祯祥。”祯祥之事见于上世者\n不一。自后世狐鸣篝火之术兴，图谶纬书往往伪托，是以圣君\n贤相戒在下不许言瑞。要之天地灵异之气，日流行于宇宙，而\n与人心相感召，顺气应之则兆而为祥，逆气应之则化而为妖。是\n则符瑞之见于世者，不必侈其事，而何可谓无其理也？唐刘庚\n氏著《稽瑞》一卷，广征载籍，博纪休祥，炼事成文，俪句以\n配。又恐后之读其辞而昧所自也，并自为之注。唐时去古犹近，\n秘阁所藏，多人间未见之本。迄今按注中篇目，半归放失。甚\n矣，古书之不传者多矣！按，是书亦见王厚斋《玉海》祥瑞类\n中。遍征各家书目，俱不载。曩时虞山陈君子准，博雅嗜古，购\n藏宋元刊本，偶获是书，珍同宝笈，即名其藏书楼日 “稽瑞”，\n志喜也。欲重刊行世，会病殁不果。今年春，顾生湘购得之，偕\n其弟浩校勘付梓，属余为序。余作而叹目：“善哉，两生之好古\n也！”是书历干余载以来，不大显于世，其不就淹灭者几希。陈\n\n关键词：丙丁龟鉴 杂占 术数全书"
