   "content": "【术数全书·上册·春秋占筮书·第3/7节】（公有领域原典·清毛奇龄·占筮·Vision OCR）\n\n归妹睽孤，寇张之弧。\n此指获晋侯，并归晋侯言。夫归妹之所之者，睽孤也。\n之彼为敌，则睽孤者寇也。然而其词曰：“先张之弧，后脱\n之弧。”夫犹是弧也。而寇张之，寇忽脱之，则犹是晋侯而\n寇获之。寇忽归之，其象正同。\n侄其从姑，六年其逋。句。逃归其国，而弃其家。读孤。明年，其\n死于高梁之虚。墟同。\n，此下皆指子圉事言。子圉以十六年质秦，秦妻之。二十\n二年，子图逃归。二十三年，惠公卒，子圉立，是为怀公。\n二十四年，秦穆纳公子重耳，怀公奔高梁，重耳弑之。此其\n事也。今筮者谓归妹以震兄嫁兑妹，则火本为震所出，故以\n嫁女言之。则离火者震木之女也，而以归妹言之，则离火者\n又震兄之子也。母女为姑，而兄子即为侄。则同此一离，而\n姑侄并居，有似乎从之者然。\n顾以环占言之，不曰震之离亦离之震乎？卦盛极必反。\n自震之一离，而两卦上下合成四离，两正两互。火炎极矣，极\n则离必之震。故自上之初，阅六爻而上又变，则六年矣。六\n年而离上之刚，仍变震柔。变者，逋也。逋则震为宗国，今\n复逃归。而所妻之家，所云男以女为家者，亦弃如敝屣，岂\n非离亦之震乎？然而六爻相巡，一周而尽，阴生阳死，不俟\n多日。况上刚既亡，将向之一梁高出，岿然横亘者，亦变而\n为墟。归于是，死亦于是矣。此隐括晋惠、子圉两事，而预\n断之者。高梁，晋邑。后子圉被杀，果在其地。或谓此筮在\n昔人相传已久，服其神验，故圉死之地，即名高梁。此死后\n称之，非先有其地者。然此皆少见多径，以小人之腹，妄度\n君子，欲为回护，而反见其陋。成季未生时，卜者谓当名\n友。及生，而果有文在其手曰友，因名之。此在百余年后，\n赵简子史墨犹能道及。不知此腹中友字，当生后刺之，抑先\n有其文者？试亦度之。\n张文楚曰：环占法，前毕万筮仕，传既占屯震之坤为诸\n侯，又转占比坤之震亦为诸侯，谓之终"
