   "content": "【术数全书·上册·春秋占筮书·第1/7节】（公有领域原典·清毛奇龄·占筮·Vision OCR）\n\n此大岳也。大岳者姜姓，此必姜氏之国也。然而物有兴衰，\n卦既变否，则必先有否而大至焉。故大岳配天，天子祭天\n地，则岳渎配之。今否上有天，山自能配。然而自观之否，\n约有四山。观一大山，否又一大山，而究之合两为一，总\n成一否艮泰震之大山。否为大艮，犹泰为大震。总见筮法。能有\n两乎则必衰，陈而后此国昌。其周史筮词，有如是者。\n及陈之初亡也，陈桓子始大于齐。其后亡也，成子得政。原文皆\n有删无改。后仿此。\n此附记后验文也。昭八年，楚灭陈。哀十七年，楚复灭\n陈。故有前后亡。陈桓子，即无宇。成子，田常也。敬仲至\n田常，约有七世。又三世灭齐，已十世矣。十者阴数之尽。\n《系词》：“地数十”。观否皆内坤，故与数合。\n附：唐人《定命录》：天宝十四年，王诸入解，筮，遇乾\n之观，谓已及宾王，而大人未见。以乾五不动也。遂遇禄山变\n而返。比以贡士宾兴解宾王，颇合筮法。但观互为坤，坤在\n《九家易》日为乱，在《虞氏易》日为师。而内坤离位，则\n《说卦》直日为甲胄，为戈兵。此与禄山之变，一何骇切！向\n遇周史，则又疑鬼疑神矣。始知圣人设筮，无时不告。而世\n卒无知之者，因附识此。\n闵元年传 初，毕万筮仕于晋，遇屯下震上坎三三之比下坤上坎三\n三。\n毕万，毕公高之后，仕晋为大夫。晋侯初作二军，万为\n车右。以灭魏，逐賜万以魏。其后分晋有国。此筮仕晋之始\n也。\n辛廖占之，曰：“吉”辛廖，晋太史。\n屯固比入，吉孰大焉，其必蕃昌。\n何以吉也？夫屯之为义也，下震动，而上坎险，皆《说\n卦》文。动而得险，故日屯。比之为义，下坤土，而上坎水，\n水土相比，故曰比。然而屯贵贞守，卦所云“居贞”，又云\n“利贞”者。贞也，即固也。比贵亲切，彖所云比辅，象所\n云比孚者，皆亲切者也。切者，八也。所守既贞固，而与\n物善八，则于以筮仕，有何勿吉？而吾并卜"
