   "content": "【术数全书·上册·春秋占筮书·第7/7节】（公有领域原典·清毛奇龄·占筮·Vision OCR）\n\n附：《吕氏春秋》：孔子筮得责三三，下离上艮。曰：“不\n吉。”子贡目：“何谓也？”曰：“夫白而白，黑而黑，贲亦\n安吉乎？”《家语》亦云：“非正色之谓也。”\n山火为十二章饰色之二，故名贲。贲者，饰也。但绘\n山于衣，绣火于裳，并皆正色。而独此卦义，从来以不正\n色为解。如京房云：“五色不成，谓之贲是也。”特其所云\n不正者，则《毛传》云：“贲，黄白色也。”郑玄、王肃说\n此卦，亦皆云黄白色。即杨雄《太玄》确首次二曰：“黄不\n纯，屈于根。”注：《易》贲卦，山下有火，黄白色也。今\n孔子所云，有黑色而无黄色，即《易》文贲如、皤如、白\n马、白贲诸语。又似祗有白色，而并无黄黑二色。此皆无\n可考辨者。况筮法论色，亦属创见，故附载此。\n《汉书》：武帝伐匈奴，筮之，得大过九五。巽下兑上三\n三。太卜因谓匈奴不久当破，但取象词“何可久也”一语。\n爻词：“九五，枯杨生华，老妇得其士夫，无咎无誉。”象曰：“枯杨\n生华，何可久也？老妇士夫，亦可丑也。”乃遣贰师伐匈奴。后巫\n蛊事发，贰师降匈奴。武帝咎卦兆反谬。今以《五易》法\n筮之，则此九五，在本封为兑中，在大壮所来为震中。大壮，\n上震改上兑。兑刚卤，《说卦》。而震以出之，此北伐之象。\n但大过通视，合为大坎，而互当重乾之末，进承一坤。龙\n战玄黄，正在此际。幸乾坎二位，皆居北方。坎正北，乾西\n北。我以南向北，则我南为凯，彼北为败，所以能破匈奴兵。\n\n关键词：春秋占筮书 占筮 术数全书"
