   "content": "【术数全书·上册·春秋占筮书·第6/7节】（公有领域原典·清毛奇龄·占筮·Vision OCR）\n\n色也。裳，下之饰也。元，善之长也。中不忠，不得其色。下\n不共，不得其饰。事不善，不得其极。外内倡和为忠，率事以\n信为共，供养三德为善，非此三者弗当。\n此皆就《易》义，以阴断其事，即筮词也。外疆二语，\n是合断两卦者。坎险为外疆，坤顺内温，以遇与之，即\n内外也。忠信者，即前所云忠信之事也。故日以下则专断\n坤卦。谓黄裳元吉，岂黄裳而即吉乎？黄为中色，裳为下\n饰，必元善而后能吉。向使为中者无忠心，则必失臣道，安\n有臣象？黄色，臣象。下不共，则上不率下，安所整饰？其后\n费邑亦叛蒯。况事无忠信，则元善已失，安能终事？极者终也。\n是必同事有忠者，公子憋，叔仲小，皆不忠。下有信者，其后蒯\n之臣司空老祁、虑癸，以盟信逐蒯。且合忠信与共为三德，以统\n成元善则可当，非是勿当也。\n且夫《易》，不可以占险，将何事也！且可饰乎？中美能黄，上\n美为元，下美则裳，参成可筮，犹有阙也。筮虽吉，未也。\n、\n此专断比词者。且坎者，险也。坎虽隐伏，《说卦》。而\n词日显比，比五爻词。则其险已著。况外卦坎位而又变，而\n尚以坎，则其为大险，有不容隐伏焉者。假目筮《易》不\n可以占险，则所占何事？况占有贞悔，并非可以黄裳一饰，\n谓足掩蔽了事也。夫黄裳之文在中，坤五爻词。与显比之位\n正中，比五爻词。祗中美也。然必推比彖之元永贞，与显比\n之上使中，一彖词，一爻词。皆本元善，而后为上美。否则徒\n饰下美，而不参成以筮之，则邑人不诫。亦比词。将有借在\n上之元，与在中之忠，以责其多阙失者，其后叛蒯者，亦终以\n群臣不忘其君为言。筮虽吉，未也。\n附：东汉永建三年，立大将军梁商女为贵人，筮之，亦\n得坤三三之比三三，与此筮同。当时解之者，但日元吉，坤\n五爻词。正中而已。比五爻词，位正中也。其后进为后。顺帝\n崩，进为皇太后。以无子，立他妃子临朝，"
