   "content": "【术数全书·下册·出行宝镜·第6/6节】（公有领域原典·撰人不详·出行择吉·Vision OCR）\n\n男女，阴阳交以起一也。水者，五行始焉，元气之凑液也。”《管\n子》云：“水者，地之血气，筋脉之通流者，故曰水。”许慎云：“其字\n象泉并流，中有微阳之气，其时冬。”《尸子》云：“冬，终也。万物至\n此终藏也。”《礼记》云：“冬之为言中也，中者，藏也。其位北方。”\n《尸子》云：“北，伏也。万物至冬皆伏，贵贱若一也。”五行之时及\n方位，故分而释之。\n二论支干名\n支干者，因五行而立之。昔轩辕之时，大挠之所制也。蔡邕\n《月令章句》云：大挠采五行之情，占斗机所建也。始作甲乙以名\n日，谓之干。作子丑以名月，谓之支。有事于天，则用日。有事于\n地，则用辰。阴阳之别，故有支干名也。而名有总别，先论总名，\n次言别号。总名支干者，干字乃有三种不同，一作干，二作竿，三\n作干字。今解竿字者，此支竿既相配成用，如树木之有支条茎竿，\n共为树体，所以云竿。又作干者，干济为义，支者，支任为义，以此\n日辰任济万事，故云支。又作干字者，亦是竿义，如物之在竿\n上，能竖立显然，故亦云辛也。世书从《易》，故多干也。次别号者，\n《诗纬推度灾》云：“甲者，押也。春则开也，冬则阖也。”郑玄注《礼\n记月令》云：“甲者抽也，乙者轧也。春时万物皆解，孚甲自抽轧而\n出也。”丙者柄也，物之生长，各执其柄。郑玄云：“丙者，炳也。夏\n时万物强大，炳然著见也。”丁者，亭也。亭，犹止也。物之生长，\n\n关键词：出行宝镜 择吉 术数全书"
