   "content": "【景祐六壬神定经·景祐六壬神定经·OCR第1/8节】（公有领域原典·宋杨维德·六壬）\n\n五行纯粹，入其贵格。盖遇食印长生，皆吉神也。必主夫妇诸和，琴瑟喜调，\n和鸣鸾凤矣。《造微赋》云：最喜食生食旺，不可食耗食空。又云：食神宜居\n生旺乡，神煞爱逢衰死地。禄马互换者，命逢交互，禄马全逢于命，合于兰\n台贵格，亦名活禄活马格矣，必主荫叙贵子，官居五府矣。群书引证见前。\n详其吉会，乃喜运并防灾。寡宿宜避，孤神可惧。吉会乃喜运\n并防灾者，命逢行年，岁运禄马，皆在生旺之地，而生我元命，谓之吉会，主\n吉庆之事，若克于元命，兼二运交并，名凶会，定主灾殃之事矣。珞琭子云：\n虽运并而未必为灾。又云吉会、凶会、伏吟、返吟。寡宿宜避，孤神可惧者，\n此乃二神，乃逐年方位，进前一辰为孤，退后一为寡，进主阳不利父，退\n主阴不利母，常术于男忌孤神女忌寡宿。然只宜回避，可忧可惧。盖不可犯\n之。《消息赋》云：岁星莫犯于孤神，天年忌逢于寡宿。\n从劫煞兮思虎之寡，守将星兮权谋之深。命从劫煞者，乃五行\n昏独之神。又云：阴气尤毒，谓之煞也。其神常在五行气绝处，寅午戌人火\n绝在亥之类。仿此。即亥是劫煞，若君子得之则气刚智勇，宜为右职，若小\n人得之，则放僻邪侈，廉所不至。生旺则出言多谋，死绝则执拗内狠。《兰台\n赋》云：劫煞沉毒多谋。《壶中子》云：劫煞倘同生气，阃外持权。袁天纲云：\n劫神包裹遇官星，主执兵权助圣明，不怒而威人仰慕，顿令夷夏悉安荣。命\n守将星者，子午卯西生人，本命守将星之位，常居驿马，后二辰是也。命逢\n必主持权统兵，威声万里人也。袁天纲云：将星文武两相宜，禄重权高足可\n知。不作宰臣清要职，便居帅府拥连旗。《兰台赋》云：将星飞马入天庭，必\n为大将。珞琭子云：崇为宝也，奇为贵也，将星扶德，天乙加临。\n胆怯者下有不顺，性凶者干来上侵。下有不顺者，命元反克于本\n命，五行不相和顺也。须要明其神煞生克，方可断其贵贱矣。干来"
