   "content": "【景祐六壬神定经·景祐六壬神定经·OCR第5/8节】（公有领域原典·宋杨维德·六壬）\n\n释刑第十六\n《传》目：刑者，刑戮之谓也。一日衰谢之刑，谓金木水火士\n正刑。二日制御之刑，谓十干之刑也。三日不逊之刑，谓十二克刑。\n冀奉传曰：金刚火强，各在其方。木落归根，水流趋末。\n已、酉、丑，金之位，在西方。言金恃其刚，物莫与对。阳\n气八月从西而入，因而挫之，故金刑在西方。\n寅、午、戌，火之位，在南方。言火恃其强，物莫与对。阳\n气五月生于午，因而挫之，故火刑在于南方。\n亥、卵、未，木之位。木落归本，言叶落复根，亥卯未，木\n之根，刑在北方。言木恃其荣观，故阴气刑之，使调伤也。\n申、子、辰，水之位，水流趋末，水性东流，逝而不返，其\n谓之末也，故水刑在东方。言水恃阴德，故阳刑使之不归也。\n术數全书 中卷\n土位在中央，寄旺四季，以未为长生，丑为冠带，墓在辰，\n天刑在戌。此言土力最大，天能刑之，故天刑在戌。制御之刑\n者，谓十干也。辰来克日为逆乱，故加刑以制御之。凡干刑所\n加，战斗不出其下。甲刑举申，乙刑在酉，丙刑在子，丁刑在\n亥，戊刑在寅，已刑在卵，庚刑在午，辛刑在已，壬刑在戌，癸\n刑在未。\n不逊之刑者，谓十二支也。义有三段：\n第一寅刑巳，巳刑申，申刑寅，为无恩之刑。言寅中有杂\n火，不恤已中杂金，故寅刑巳。已生庚金，又效尤巳里之杂土，\n不恤申中之杂水，水故往刑申。申立下已，见所生已里之土被\n寅刑，故又往刑寅。此为无恩之刑也。\n第二侍势之刑者，言未土恃长生，而欺丑之始冠带，故未\n刑丑。丑恃冠带，而欺戌土之先被刑，故丑往刑戌。戌再迁其\n怒，自恃旬首甲戌，而往刑旬末癸未。此为恃势之刑。\n第三无礼之刑者，言阳精自生日，阳气在子，而卵为日门，\n子为卯父，鼎立无卑恭之礼，是以卵子为无礼之刑也。翼奉传\n日：子为贪狼，卵为阴贼，王者为忌失之辰。辰午西亥自刑，义\n见上矣。\n、\n释害第十七\n《传》日：害者，妨也，在"
