   "content": "【景祐六壬神定经·景祐六壬神定经·OCR第8/8节】（公有领域原典·宋杨维德·六壬）\n\n癸日，忌未时。\n右忌日时不可占事，误用者当损用式之人也。\n释次客第三十三\n《玄女》日：阳将临正时，先用后三，次用前五。阴将加正\n时，先用前五，次用后三。\n假令十二月占事，第一人，用月将神后；第二人，用月将\n后三从魁；第三人，用前五功曹。余皆仿此例。\n《灵辖经》日：用次客法，第一客，月将加正时；第二客，\n用月建加太岁；第三客，用太岁，加月建；第四客，用月建，加\n日干；第五客，用发干，加正时；第六客，用月将，加日干；第\n七客，用月将，加太岁；第八客，用太岁，加月将；第九客，用\n月将，加本命；第十客，用月将，加行年；第十一客，用太岁，\n加本命；第十二客，用太岁，加行年。\n释次筹第三十四\n《灵辖经》日：次筹之法，皆以第—筹用月将。若用阳将，\n则先用后三而前五；若用阴将，则用前五而后三。逆顺更筹，终\n而复始。一法：以太岁上神，三传以知三事；以月建上神，三\n传以知三事；以日上神，三传以知三事；以正时上神，三传以\n知三事，则十二筹次客备焉。\n释行年第三十五\n《灵辖经》日：男一岁，从丙寅顺行，从一岁移一辰。十一\n岁丙子，二十一岁丙戌，余皆仿此，终而复始，顺行而数。女\n一岁，从壬申逆行，移一辰一岁，壬申。十一岁，壬午，余皆\n仿此。终而复始，逆行而数。\n释将传第三十六\n《玄女》日：六壬之道，皆取三传，相生则吉，相克则凶。\n一传见天乙贵人诏命，朱雀文书口舌，六合嫁娶婚姻，勾陈斗\n讼田土，青龙贞观君子，天后妇女贵人，太阴所处娶妇，玄武\n阴私奸宄，太常冠带仕宦，白虎死丧折伤，天空万事欺诒，腾\n蛇惊恐怪异。\n《集神经》云：王气所胜，法忧县官；相气所胜，法忧财物；\n死气所胜，法忧死丧；囚气所胜，法忧刑狱；休气所胜，法忧\n疾病。\n《神匮经》日：子传母而失礼，母传子为顺道。失礼则所作\n违碍，顺道则庆无不疑。此用式之常例。"
