   "content": "【术数全书·下册·李虚中命书·第11/12节】（公有领域原典·唐李虚中·命理·Vision OCR）\n\n有潜伏之气，从下如流，虽名大智，非轩昂超达之士，不可姑息，顺则安\n平，逆则奸危。庚申为白虎之神，利于武而不利于文，有抱道孤羁之性，\n善中严内，色厉内荏，有仁义，好幽僻。辛酉为太阴之神，怀肃杀之气者，\n有清白之风，为文章和易不世之才。然后各以亲疏休旺定之也。\n水土名用\n土本无一方之气，从水妻之义也。阴阳各逐，四时成就。辰\n中有乙，则木土成之，故在寅卵辰中之土，随木之生旺也。魁里藏辛，则\n金土成之，故在申酉戌之土，随金之生旺也。贵神得癸，则水土成之，故\n在亥子丑之土，随水之生旺也。未隐丁火，则火土成之，故在已午未之土，\n随火之生旺也。大体如此，则其土之用，皆喜于辰戌丑未也。戌气从戌从\n已，戌火钟而土育，已火极而土成，已气从亥从午，亥火之绝也。土生午\n火之旺也，土音盖已午为火极，成亥为火熄，父母极熄而子孙成之，与水\n之异也，二气俱逆，戌得丑而为已得未，已自亥逆至米旺，戌自已逆至丑\n旺，天地之中库于辰，金土之会成干戌。然则水土当育于寅。阴阳之中，\n卵西为无止之地，子午为夫旺妇极之所。丑乃木立形而上藏，甲为金成而\n土衰，成作魁而利，乃土发之独用，不从四时之义也。其立用之方，盖士\n无定形，虽载其文，而未可究其指，故存之以待来者。\n•\n理发灶前，妇安夫家。《艺文类聚》卷十七人部，《太平御\n览》卷三百七十三人事部。\n用麻子中人，桐叶米汁煮之，得二十日，发长。《艺文类\n聚》同上人部。\n孤桃汁之券，令鸡鸣。注日：取孤桃南北行枝，长三尺，折\n以券。涂以三岁雄鸡血，夜居栖下则鸣。《艺文类聚》卷八十\n六果部，又《太平御览》卷九百十八羽族部引云：孤桃之象，令\n鸡夜鸣。\n八月榆橋，音而。令人不饥。《艺文类聚》卷八十八木部。\n注日：以美酒渍榆橘，曝干，以清粱米、紫苋实蒸令相合，欲\n不食者三指撮酒以服之，"
