   "content": "【术数全书·下册·李虚中命书·第3/12节】（公有领域原典·唐李虚中·命理·Vision OCR）\n\n子甲申；丙丁贵在亥西，丙得辛酉辛亥，丁得壬寅壬辰，如此\n之类谓之贵合。甲食丙乙食丁，丙丁贵在西亥，甲得丙寅丙辰，\n乙得丁酉丁亥；庚食壬辛食癸，壬癸贵在卵已，庚得申壬成，\n辛得癸卵癸巳，如此之类，谓之贵食。有贵合则官多称意，有\n贵食则禄多称意。二者兼之，官高禄重，无往不利。阁东叟书。\n天乙贵神合者，谓天乙在，贵神亦合上是也。甲戊庚在子，\n午乙己在丑，已两丁在寅，辰壬癸在申，成辛在亥未，皆主大\n福，遇两合以上者主贵。三命提举。\n李虛中命书\n李虚中命书卷中\n通理物化\n清气阳为天，查查而上冲乎阳；浊气阴地，冥冥而下从\n其物。太虚之先升寂何有？至精感微而真一生焉，直一运灵而元气自化，\n自化元气者，乃无中之有，有中之无。广不可量，微不可察，氲渐著，\n混漠无倪，万象之端，朕兆于此。于是有清通澄朗之气，化而为天；浊滞\n烦昧之气，积而为地，故清者自浊而澄，高者自下而上。天高而浮，地厚\n而沉。浮者有彰动之象，故为阳；沉者有寂没之理，故为阴。清者上腾高\n而纯阳，故充满；浊者下沉密而纯阴，故冥寂。而万物从化之，故冲于上\n者为阳，而生万物；沉于下者为阴，而成万物，然而实始于一者也。\n清浊交分，人物混成，造化始于无，相因而日三生。太朴之\n散乾坤之形，分体一定乎尊卑，有阴阳之相摩，有刚柔之相推，变动以行\n其道，经纬以成其事。凡垂象于天者，莫非文也，有高下之相倾，广轮之\n相推，动静之所生，形势之所持。凡具质于地者，莫非礼也。故万物生于\n其间者，亦且出机入机，出冥入冥，方生方死，方死方生，域于轮转之地，\n而机之动不能自己，故草木黄落而菊始华，仓庚鸣而鹰以化。一根异之细\n不知谁与之扶持，一昆虫之微，不知谁与之生死。戢戢而动植，非物与之\n雕刻也；芸芸而归根，非物与之揪敛也。自消自息，自智自力，自形自色，\n曾不知"
