   "content": "【术数全书·下册·李虚中命书·第4/12节】（公有领域原典·唐李虚中·命理·Vision OCR）\n\n.三才有阴阳之天地，五行运物化之人伦。分阴阳则为天地，立\n父子则为人伦，故干阳也。亦有乙丁已辛癸之为明，支阴也，亦有子寅辰\n午申戌之为阳，是知阴阳之相覆，奇偶相匹。故万物化成，生者为父为母\n为子为孙，配之为夫为妇，以别人伦之要也。\n李虛中命书\n天五地五则为造化之先，除其数则纳音之用。天地变通，二\n五为十，终成万物，始一终五皆阳，合之为六则阴，为六五数外，即天地\n数所纳五行之数也。假令水得五者，是本音以土权碍也。然后有音，故丙\n子丁丑共得三十之数，而六五皆土而得纳音为水也。火得一者是火无音，\n因水沃之，然后有音，故戊子己丑共得三十一数，而除六五而有一数而纳\n音得火也。木得三者盖木是本音，故壬子癸丑共得二十八数，而有五之数\n是三数而纳音得木也。金得四者亦金是本音，而甲子乙丑共得三十四数，\n而除六五之数外是四数乃金也。土得二者盖土本无音，火陶之然后有音，\n故庚子辛丑共得三十二数，而除五六之数而纳音为土也。故经云：先甲后\n子纳音金者数也，得此则彼可知也。\n自乾而生顺，从坤而产逆，阴阳机括于五行，五行之体依\n八卦。父生顺，母生逆，假如甲已干正月建丙寅丙丁火，故木生顺，母\n已之干在木死为逆，故甲为父已为母，在寅之家，天生水，则由乾为属金，\n金水也，故自乾生而顺及纳音，即甲子乙丑金为首，盖乾纳甲子即是天五\n地五于坤数中生逆，其终数而生，亦由先九而后至四数也。阴阳者乾坤，\n故金土一而两之以备五行，五行分体用而为八卦。\n火爱乾为会，水利巽而亨，岁守坤乡，金藏艮位。乾纯阳也，\n处西北，故至亥而显明。水性本下，巽出东南顺下也，故水巽为利也。坤\n则成物，岁以终之，故至申万物介然守礼，用艮终始万物而在于坤，故金\n至寅终藏于土下。\n木落粪本，水流趋末，火显诸用，金蔽于光。各任性乡守\n故坤乡，水趋末则利"
