   "content": "【珞琭子三命消息賦注·珞琭子三命消息賦注·提要】（公有领域原典·宋徐子平注/珞禄子·命理）\n\n欽定四庫全書　　　　　子部七\n提要\n珞琭子三命消息賦注　術數類五(命書相書之/屬)\n臣等謹案珞琭子三命消息賦注二卷宋徐\n子平撰珞琭子書為言禄命者所自出其法\n専以人生年月日時八字推衍吉凶禍福李\n淑邯鄲書目謂其取琭琭如玉珞珞如石之\n意而不知撰者為何人朱弁曲洧舊聞云世\n傳珞琭子三命賦不知何人所作序而釋之\n者以為周世子晉所為然考其賦所引有秦\n河上公又如懸壺化杖之事皆後漢末壺公\n費長房之徒則非周子晉明矣是書前有楚\n頤序又謂珞琭子者陶宏景所自稱然禄命\n之說至唐李虚中尚僅以年月日起算未有\n所謂八字者宏景之時又安有是説乎考其\n書始見於宋藝文志而晁公武讀書志亦云\n宣和建炎之間是書始行則當為北宋人所\n作舊稱某某皆依托也自宋以來注此賦者\n王廷光李同釋曇瑩及子平四家子平事蹟\n無可考獨命學為世所宗今稱推八字為子\n平盖因其名劉玉已瘧編曰江湖談命者有\n子平有五星相傳宋有徐子平者精於星學\n後世術士宗之故稱子平又云子平名居易\n五季人與麻衣道者陳圖南吕洞賔俱𨼆華\n山盖異人也今之推子平者宋末徐彦昇非\n子平也云云其説不知何所本然術家之言\n百無一真亦無從而究詰也其注久無傳本\n惟見於永樂大典中者尚為完帙謹採掇裒\n輯釐為上下二卷以符宋志之舊其中論運\n氣之向背金木剛柔之得失青赤父子之相\n應言皆近理間有古法不合於今者是則在\n後人之善於别擇耳又考三命通㑹亦載有\n珞琭子寥寥數語與此本絶不相合盖由原\n書散佚談命者又依托為之偽中之偽盖不\n足據要當以此本為正也乾隆四十六年三\n月恭校上\n總纂官(臣/)紀昀(臣/)陸錫熊(臣/)孫士毅\n總　校　官(臣/)陸　費　墀\n\n关键词：珞琭子三命消息賦注 命理 珞琭子三命消息賦注·提要"
