   "content": "【三命指迷賦·三命指迷賦·提要】（公有领域原典·宋徐子平注/珞禄子·命理）\n\n欽定四庫全書　　　　　子部七\n提要\n三命指迷賦一卷　　　術數類五(命書相書之/属)\n(臣/)等謹案三命指迷賦一卷舊本題宋岳珂\n補注珂所著有九經三傳沿革例媿郯録程\n史金陀粹編寶真齋法書贊玉楮集諸書而\n不聞其有是書宋史藝文志亦不著録惟程\n史中有珂與瞽者楊長論韓侂胄禄命及論\n幕官袁韶禄命一條其説頗詳則珂亦頗講\n是事或術家因而依托歟自元明以來諸家\n命書多引其文以此本檢勘並相符合知猶\n宋人所為也文淵閣書目載是書一部一冊\n葉盛菉竹堂書目亦有是書一冊是明初其書\n尚存今則久無單帙行世惟永樂大典所録\n尚首尾完具謹採掇釐訂編為一卷附之術數\n類中以備參考而岳珂之名則削除不載焉\n書中所論大抵專主子平於夾馬夾禄拱庫\n拱貴辨論詳盡往往為他家所未發而拱庫\n一條尤稱精晰其他文義通達亦多有可取\n惟專以月建及胎元為推測之本則不為定\n論葢月建是行運所主要必常以日時參之\n人生十月而産固為常期然氣稟不齊亦有\n逾期不及期者若悉以十月為限則刻舟求\n劍未免轉失之支離是又在學者之决擇矣\n乾隆四十六年九月恭校上\n總纂官(臣/)紀昀(臣/)陸錫熊(臣/)孫士毅\n總　校　官(臣/)陸　費　墀\n\n关键词：三命指迷賦 命理 三命指迷賦·提要"
