   "content": "【珞琭子三命消息賦注·珞琭子三命消息賦注·卷上·1】（公有领域原典·宋徐子平注/珞禄子·命理）\n\n欽定四庫全書\n珞琭子三命消息賦註卷上\n宋　徐子平　撰\n元一氣兮先天禀清濁兮自然著三才以成象播四氣\n以為年(元者始也一者道生一冲氣也有物混成先天/地生以㸔命法論之如人初受胎月在母腹中)\n(男女未分以四柱言之則知人本命也尚未有生月日/時即貴賤夀夭未分故云一氣以大道言之則混一氣)\n(而生育天地也主祖宗之宫也隂陽既分清氣為天濁/氣為地地法天天法道道法自然以命術言之則如在)\n(母胎中以是成形男女已分也以大道言之天地分也/以四柱言之則生月是也主父母宫天地人為三才以)\n(命術言之是人生日是也乃人身自得之宫㸔下臨何/宫分也四氣者布木火水金以為四時各旺七十二日)\n(土旺四季各旺十八日故為一年五行之休旺也以㸔/命論之是人生時也以四柱論之本命生月生日生時)\n(四柱也每一宫有三元有天元人元支元生時主子孫/也更㸔生時天元不居休敗居於旺相則佳矣死囚則)\n(見多而/晚成)以千為禄向背定其貧富以支為命詳逆順以\n循環(干者是生日天元也㸔干下有何支支内有何人/元而與生日天元為禄或有禄印或有財帛假令)\n(六甲生日人甲子生旺甲寅建禄甲辰為財庫甲午為/妻財甲申為官印甲戌為財官其甲子以水生木如秋)\n(生并十二月生則有官貴命官印無失甲以庚辛為官/印為子冇癸善制其丁故曰癸乃甲之印綬也更須消)\n(息四柱内外吉凶輕重而配其休祥其言不可大疾疾/則不盡善矣向者要生日天元向其禄馬也如無禄馬)\n(向其財帛或有向其壽限向其旺相也假令六甲生日/天元若得夏至生而居辰戌丑未并丑位之上則冇財)\n(帛及有祖基若是秋生居巳酉丑申戌四柱之内别無/丙丁則甲之向禄也甲以金為官印秋生金旺故曰向)\n(也若運到西方者亦向禄也運行南方及四季亦向財/也若生月内有官印於生日天元則主官出祖宗如生)\n(月及支内有財於生日天元則主有祖財若生時支内/有財别無刑衝尅破則主自立財"
