   "content": "【术数全书·下册·乾元秘旨·第4/5节】（公有领域原典·清舒英·命理·Vision OCR）\n\n名顶度不可概论煞也。庚年人行奎木煞度，居大位，掌重权者，\n查原木与气冲照已经合化，天官金与太阳俱在斗躔，则奎木乃\n天官与太阳贵气所通故也。有辛年人行娄金煞度馆选者，查金\n即科名，木在阳躔，则即以科名近阳也。总之，七煞止忌其混\n官。既不混官，则另视其气之所并而已。盖即一星常在数用，一\n用，亦有不同之理，特因煞而载详之。\n七年每月行二十一分零，两个月零二十四日行一度。\n一年，该四度十七分有奇。\n二年，该八度三十四分有奇。\n三年，该十二度五十一分有奇。\n四年，该十七度八分有奇。\n五年，该二十一度二十五分有奇。\n六年，该二十五度四十二分有奇。\n七年，合计三十度。\n八年每月行十九分，峡三个月零六日行一度。\n一年，该三度四十五分。\n二年，‘该七度三十分。\n三年，该十一度十五分。\n四年，该十五度。\n五年，该十八度四十五分。\n六年，该二十二度三十分。\n七年，该二十六度十五分。\n八年，合计三十度。\n十一年每月行十三分零，四个月零十二日行一度。\n一年，该二度四十三分有奇。\n•\n二年，该五度二十七分有奇。\n三年，该八度十分有奇。\n四年，该十度五十四分有奇。\n五年，该十三度三十八分有奇。\n六年，该十六度二十一分有奇。\n七年，该十九度五分有奇。\n八年，该二十一度四十九分有奇。\n九年，该二十四度三十二分有奇。\n十年，该二十七度十一六分有奇。\n十一年，合计三十度。\n某宫行几年，惟七年、八年、十一年，尤须逐年扣清，特\n另开于右。\n卷第一\n扬子云《太玄》，其法本于《易纬卦气图》。卫先生《元\n包》，其法合于《火珠林》。皆革其诬俗，而归诸雅正者也。伏羲\n始作八卦，因而重之为六十四，是名先天，陈希夷所传《先天\n图》是也。其数有二，圆图者，天也。自一阴一阳，各六变为\n三十二阴三十二阳者，运行数也。方图者，地也。八卦纵横上"
