   "content": "【术数全书·下册·乾元秘旨·第1/5节】（公有领域原典·清舒英·命理·Vision OCR）\n\n正财。\n伤官\n凡天官遇伤者，须见正财。若见正财，转能生官。盖伤生\n财，财生官也，故有行伤官度。发者，非伤官在正财度，即正\n财在伤官度。伤财互躔，行伤度胜于行财度。昔人有专看天官\n正财伤官三星者，详其聚散，审其衰旺，知其生中有伤、伤中\n有生，从而断之，无不立验。是天官遇伤官，必须正财。若无\n正财，即须正印以制之，尤须阳年以偏印，阴年以七煞合化之。\n食神\n食神取其制煞，因之煞去官清。但阳年颇忌其合官，阴年\n亦忌其剥官。如煞在对官，官在同宫，则只能合近地之官，剥\n近地之官，而不能及煞，煞仍自如何也。对宫疏而同宫亲也。\n正印\n正印，乃所以制伤官也。但阳年与偏财合化，既无以制伤\n官，又虑天官有藉于偏财，为之阻隔。阴年与食神合化，既无\n以制伤官，又虑七煞待制于食神，为之消灭。\n偏印\n偏印能制食神，使食神不能制七煞，其害最大。惟食神与\n天官有碍，则又赖偏印之制。阳年与伤官合化，可以助官。阴\n年与正财合化，适以损官。\n劫财\n此为十曜中最恶之星。阳年虽有合七煞之休，阴年实有合\n偏财之咎，经但专主伤妻，自历年试之，正不止此。与日有关，\n即行劫度，克父。与月有关，即行劫度，克母。与弟兄有关，即\n行劫度，克弟兄。与子孙有关，即行劫度，克子孙。虽不行劫\n度，但逢劫顶度，亦诸恶毕集，而且耗散有之，疾病有之，居\n官者降罚亦有之。若与妻主有关，妻主又不得气，常常断弦。与\n子星有关，子星又不得气，每每绝嗣。与财曜有关，财曜又不\n得气，屡屡空乏，仅置诸闲散之地，尚恐招殃。倘入乎拦夹之\n乡，愈将肆虐，必得天官乃能制之，而天官又以制劫，力薄矣。\n元禄\n元禄即天禄也。果得时得地，与命主有情，多食天禄，惟\n不取其有合。阳年与正财合，无以生官；阴年与天官合，有以\n夺官。\n恩难仇用\n恩难仇用，皆五行之理。但恩难较切，尚可兼观。"
