   "content": "【术数全书·下册·乾元秘旨·第5/5节】（公有领域原典·清舒英·命理·Vision OCR）\n\n相易则通。阴阳相为用，用九以六，故乾之用在离；用六以九，\n故坤之用在坎。《参同契》曰：“《易》谓日月坎离者，乾坤之\n妙用。二用无爻位，周流行六虚，是故乾坤互变，坎离不动。当\n游魂为变之际，各能还其本体也。”凡八卦游魂之变，乾坤用坎\n离，坎离用乾坤，震艮用巽兑，巽兑用震艮，皆为阴阳互用，以\n至六十四卦。若上爻不变则皆然。是故诸封祖于乾坤，皆有乾\n坤之性也。其正以坎离为用者，惟乾坤为然。坎离肖乾坤，故\n用乾坤。震巽艮兑，体虽变而纯，可与共学。其一不变，自明\n而诚。游魂之际，为颐、中孚、大小过，则亦肖乾坤坎离也。\n先天天卦，自乾变坤，得一百九十二阴，而成六十四卦；自\n坤变乾，得一百九十二阳，亦成六十四卦。总百二十八卦。地\n卦纵横各六十四，亦总百二十八卦。《元包》八卦之变，七变而\n归魂，八卦成六十四卦。自归魂之卦又七变而复本，八卦亦成\n六十四卦，共百二十八卦也。封有六十四，天地阴阳，幽显互\n用，皆成一百二十八。故甲子六十而百二十。所以人皆有百二\n十年之寿，得其半者为下寿也。卦百二十八者，八之十六也。甲\n\n关键词：乾元秘旨 命理 术数全书"
