   "content": "【术数全书·下册·乾元秘旨·第3/5节】（公有领域原典·清舒英·命理·Vision OCR）\n\n见便以为大格局，即许以宜尊显，何愚昧至此？\n何谓七曜？相照之光，多少不同。日前后光十五度，月一\n十二度，土木火各九度，金水各七度。假令火追逐士相离七度，\n则二星沾光，呼为相会。若星光度数均者相会，则各星度数减\n半同沾光。若星光度数多少不同者，初会时度数多者先沾光，少\n者光未沾及。少者度数相及，则二星同沾光，为正会。凡二星\n同度为相会，但遇一分为相离，虽相离力尚在，为二星后光未\n尽也。若二星相会后相离一分或二分，却再有一星在后追及，星\n虽未到，光已相沾，即与后星又为初会。此论经度则然，若在\n纬度，或黄道南或黄道北，更重。如二星纬度同，经度亦同，则\n下星能掩却上星，故相会为尤紧。且此二星相会后，一星前去\n追及一星，即将先会星光移向后相会之星。假令二星东出度数\n与对黄道的赤道度数相同，如亥官二十五度与戌宫五度同，或\n二星在两处，日长短同，如一星在中官二十五度，一星在未宫\n五度，亦呼为相遇。又如火星在戌宫，木星在已官，金星在申\n宫，金离火追及木，却将火之光移向木星，似火与木亦为相遇，\n谓金先与火六合照后，与木相弦照也。又火星在戌官，太星在\n已宫，土星在申宫，土与火六合照，与木相弦，照上，將木火\n二星光聚于一处，亦为相遇。若一星在本宫，又在分定数上，与\n一星或三合或六合，或对冲二弦，相照，主星即受相照之星之\n荣落。\n何谓政余类聚？乃水与李，木与气，火与罗，土与计，一\n类分聚也。若金星居中，贵气所属，以之作命主。金无余气，理\n应位冠群僚。如水土木火作命主，非贵气所属，又不近阳，亦\n寻常人耳。贵气所属，又能近阳，终嫌其为余星分窃，仅列卿\n贰而已。\n五列形也而气存焉，三四五星同坐一宫，疏密匀停，谓之\n坐列。三四官上，疏密匀停，谓之排列。宜命主居中及高地，犹\n四五人同坐，居中者尊也。疏密不匀，谓之"
