   "content": "【术数全书·下册·乾元秘旨·第2/5节】（公有领域原典·清舒英·命理·Vision OCR）\n\n形气交孚天星与人命妙合，形气自相流通，吉凶了如指掌。有\n形吉而气凶者，有形凶而气吉者，均不可泥形而遗气焉。试思\n最近大圜者莫如恒星，次之土，次之木，次之火，次之太阳，次\n之金，次之水，最卑为月。以形而论，则高下之距实大悬殊，向\n非有气以主之，何以各系于天而不坠？又何以天道左旋而诸曜\n皆能右转也？以是知气虽渺冥恍惚，实则周浃旁皇。人受阴阳\n五行以生，亦何时何刻不与十一曜默默相融贯乎？耶律楚材云：\n各星俱合格，限度无贵气。所属终难大伸，各星俱落陷，限度\n非戾气所归，何至大屈？即有此限度，太岁尚不冲，钓亦将从\n缓，是诚识气之奥窭也。善观命者不视形而审气，气有清浊则\n命分贵贱，气有明暗则命分穷达，气有厚薄则命分大小，气有\n顺逆则命分夷险，气有善恶则命分贤奸，气有促舒则命分寿天。\n若徒以形而已，则四余拦月，五曜环阳，为格中之最巨者，岂\n皆人人富贵乎？试举一二以例其余：一康熙庚申甲申癸卯癸亥\n生人，月在子之虚，孛在卯之氐，气在酉之胃，计在成之室，罗\n在辰之翌，是四余拦月矣。木在申之毕，火在未之井，五，土\n在未之井，十六，金在午之柳，四，日在午之柳，十一，水在\n已之张，是五曜顺生而环阳矣。木为文为煞，火为偏财，土\n偏印，金为天官科名，水为魁为元禄，金水贵气所归，作阳引\n从。又递生至金水而住，若金水作命主，岂不大显？彼立命于\n戌，以火为命主，甚远于阳，仅受文木之生又带煞气，故于斗\n木文度内乡荐，后屡应保题而不用，用亦仅以教职，譬之地\n脉乃过龙非结穴也。一康辛卵庚子壬辰王寅生人，月在亥之\n危，李在申之昴，气在申之觜，罗在丑之斗，十八，计在未之\n井，是四余拦月矣。土在午之柳，金在卯之氐，水在寅之尾，十\n五，木在丑之斗，三，火在丑之斗，四，日在寅之尾，十一，是\n五曜顺生而环阳矣。土为正印，金为科名七煞"
