   "content": "【术数全书·下册·秘传水龙经·第1/11节】（公有领域原典·清蒋平阶·水法风水·Vision OCR）\n\n在，健骑四出迹之，无有也。意其为知几审微、远举绝尘之士。而\n余见玉峰卧龙山人葛芝《送大鸿北游叙》有日：“蒋子志士也。是\n役也，宁饥寒之是驱，不虞之是惧，盖将涉淮泗，历邹鲁，徜徉于\n渔阳上谷之间。”夫淮泗，韩侯之所游钓、文成所从受书地也；邹\n鲁之国，孔官之钟鼓无恙、阙里之楸檟犹存也；渔阳上谷，耿弇、\n吴汉中兴勋业所由起也。蒋之驱车其间，慨然必有所得矣。葛君\n之言如是，则又似怀材欲试、有投石横草之思者。将其人固多奇，\n著书立言特其余事，而为形家之学，又其余之余乎？并志之以俟\n考云。\n乾隆甲子又二十四年岁次丁亥鹤\n市迓亭程穆衡识\n序（二）\n自鸿蒙开辟以来，山水为乾坤二大神器，并雄于天地之间。\n一阴一阳，一刚一柔，一流一峙，如天覆地载，日且月暮，各司一\n职。后世地理家罔识厥旨，第知山之为龙，而不知水之为龙。即\n有高谈水法者，亦唯以山为体，以水为用，至比之兵之听将，妇之\n顺夫。于是山之名独尊，而水之权少绌，遂使平阳水地，皆弃置水\n龙之真机，而附会山龙之妄说，举世茫茫，有如聋聩，此非杨曾以\n来未晰此义也？古人不云乎，“行到平阳莫问龙，只看水绕是真\n龙”；又云“平阳大地无龙虎，萨漆归何处？东西只取水龙，扞着\n出三公”，其言之晓畅条达，隐隐在人耳目间，人自不之察耳。至\n其裁制格法实鲜，专书发挥未备，卒使学者面墙，无径可入。是岂\n以山之结构有定，水之运动无穷，人苟知水龙作法，将大地山河\n随所指顾，不难握神机而参造化，故引而不发，为造物惜此秘奥\n欤？夫高高在上，哀此下民，亦欲使千古不传之蕴，宣露一时。苟\n知而不以告人，为不仁；告而不以实，为不信，予不揣固陋，欲为\n后此通人彦士执辔前驱，因无极之传，发抒要妙，尽泄杨公之诀，\n俾荡然大辟。以山龙属之高山，以水龙属之平壤，二法判然而不\n相合。不惮"
