   "content": "【术数全书·下册·秘传水龙经·第2/11节】（公有领域原典·清蒋平阶·水法风水·Vision OCR）\n\n气横行，内气止生。”旨哉斯言欤！\n夫天地之气，阴与阳而已。《易》曰：“一阴一阳之谓道。”又日\n“阴阳互藏其宅，动静互为其根；阴阳相嬗，万物化醇。”郭子有\n云：“独阳不生，独阴不成。”阴阳合德，而生成之功备。故山脉之\n峙，水脉之流，各有阴阳。水者阳也，山者阴也，二者交互，不可须\n臾离也。地脉之行，藉水以导之；地脉之止，藉水以凝之。既能导\n其行，又有凝其止者，何也？盖外气既与内气复合，二气相荡而成\n物，犹夫妇交媾而有生育之功也。阳为雄，阴为雌，阳以畜阴，阴\n以含阳，即雌雄相会，牝牡相媾之情也。故曰：阴阳相见，福禄永\n贞；冲阳和阴，万物化生。此天地自然之化机也。合而言之，混沌\n之体，即万物统体一太极之妙用；分而言之，随物之物，又万物各\n具一太极之元奥也。知太极之理，则可以悟化机之妙；知化机之\n妙，则可以语形象之学矣。\n自然水法歌\n水法最多难尽述，略举大纲释迷惑。\n世传卦例千数家，彼吉此凶行不得。\n自然水法君须记，无非屈曲有情意。\n来不欲冲去不直，横不欲反斜不急。\n横须绕抱及弯环，来则之元去屈曲。\n澄清渟畜甚为佳，倾泻急流何有益？\n八字分开男女淫，川流三派业将倾。\n急泻急流财不聚，直来直去损人丁。\n左射长男必遭殃，右射幼子受灾伤。\n若还水从中心射，中房之子命难长。\n扫却罗城子息少，冲心射胁孤兼寡。\n反跳人离及退财，卷帘填房与人赘。\n澄清出人多俊秀，污浊生子多愚钝。\n大江汪洋万顷田，暗扶爵禄食五鼎。\n池湖凝聚卿相职，汪洋水朝贵无敌。\n飘飘斜出是桃花，男女荒淫总破家。\n生人出入好游荡，终朝吹唱逞奢华。\n屈曲流来秀水朝，定然金榜有名标。\n水如流去无妨碍，财丰亦主官高迈。\n水法不拘去与来，总须屈曲去仍回。\n三回五转来顾穴，悠悠眷恋不忍别。\n何用九星并八卦，生旺死绝皆虚说。\n述此一篇真口"
