   "content": "【术数全书·上册·太清神鉴·第15/22节】（公有领域原典·后周王朴·相术·Vision OCR）\n\n又不以形类，盖为声无形，但听而会意，则详酌其理。然后较\n其吉凶，万不失一也。\n五\n音\n五行散为万物，人生万物之上而声亦辨。其故木音嘹呖高\n畅，激越而和；火音焦裂躁怒，如火烈烈；金音和而不戾，润\n而不枯，玉磬流音；水音圆而清，急而畅，或条达而流，或激\n而发；土音深而不浅，厚而不薄，浑然如发在咽喉之间也。与\n形相养相生者吉，与形相克相犯者凶。\n行\n部\n行者，进退之节，去就之义，所以见其贵贱之分也。人之\n善行，如舟之遇水，无所往而不利也。不善行者，如舟之失水，\n必有澡沿没溺之患也。是以贵人之行，如水而流下，身重而脚\n轻。（《玉管照神局》注曰：“身端直如水之流下，條然而往，体不摇也。”）\n小人之行，如火炎上，身轻而脚重。（《玉管照神局》注日：“如火\n摇动，其身不正，其脚摇而动。”）故行不欲昂首而躩，又不欲侧身而\n折，太高则亢，太卑则曲，太急则暴，太缓则迟。周旋不失其\n节、进退各中其度者，至贵人也。且行而头低者多智虑，行而\n头昂者少情义。行而偃胸者愚而下，行而身平者福而吉。如虎\n步者福禄，如龙奔者权贵。如鹅鸭之步者，家累千金；如马鹿\n之骤者，奔波一世。如牛行者富而寿，如蛇行者毒而天。雀跳\n者食不足，猿踯者苦不停。龟行者福寿，鹤步者灭禄。雁行者\n聪明而贤，鼠行者多疑而贱。行如流舟者富贵，行如急犬者微\n贱。蹭蹬而来者，性行不吉；泄泄而往者，财食有余。脚跟不\n至地，穷而天寿。发足急如奔走者，贱居人下。行而左右偷视\n者，心怀望窃；行而回面后顾者，情多惊乱。大体行之贵也，腰\n不欲折，头不欲低，发足欲急，进身欲直，起走欲阔，端然而\n往不凝滞者，贵相也。行者进退去就之间，欲中规矩。不及徐\n动有理者，善也。肥人形重，行欲如飞，瘦人形轻，行欲如疑，\n此乃贵相。若斜身偏肩，如鹊之跳、如蛇之趋者，皆不善也"
