   "content": "【术数全书·上册·太清神鉴·第12/22节】（公有领域原典·后周王朴·相术·Vision OCR）\n\n肉致伤亡。承浆逢见身当丧，大海遭时主水殃。印堂白气哭爷\n娘，若在命门兄弟当。奸门若招主私动，中岳横纹家有丧。日\n月角中忧重服，法令陂池脚足伤。眼下横纹夫妇斗，准头还是\n竞田庄。地阁横遮牛马损，若侵年寿死公婆。入口分明忧口舌，\n利仓上有贼还多。\n黑色出没\n黑色初起，如乌鸟尾。将盛之时，如黑发得膏。欲去之时，\n如落垢味。五行属水。旺于冬，相于秋，囚于夏，死于春。发，\n主病灾厄。润，主死亦兵亡。枯翳客死，散主病痊。日应在申\n子辰日，旬应在甲寅旬及冬月，以旺为应。\n黑色吉凶歌\n天中必定失官勋，忽于颧上似官刑。若还至下来年上，病\n患相缠丧此身。天狱年上应狱死，高广逢时病主亡，阳尺过来\n凶可得，天庭客死在他乡。四煞贼来成凶贼，司空病疾苦缠身。\n右府生来忧此位，重眉不利远行征。额角黑广善为偷，印堂移\n徙看他州。山根必死于旬日，太阳疾病厄堪忧。牢狱至眼忧牢\n狱，法令入口形分八。更有眉头青色应，百日饮酒还醉杀。眼\n目更兼赤色间，二旬或讼见血光。外阳发被人欺劫，年上忧死\n困灾伤。男女忧他男女厄，寿上入耳卒中亡。命下甲匮遭烧死，\n准头忧病外来殃。黑发三阳黑气多，失官停职事波波。更上发\n来年寿上，天中有黑见阎罗。黑气入口死于夏，颧上兄弟妇奔\n逃。好门切忌女相干，日角若临妻亦亡。井部黑气水溺死，印\n堂退光非谬假。横飞寿上防逢灾，六十日内须应也。黑气额上\n父母死，生来眼下子孙殃。若见下来年寿上，自然病起入冥途\n．太清神鉴，\n黑气三阳至盗门，奸私贼寇岂堪论。更见黑气鼻准上，知君财\n破避无门，黑生妻部及年上，妻厄身灾非是旺。更兼入井下陂\n池，切记水殃心莫忘。黑气朦朦散面门，四季切忌小灾。若\n生口入气厨灶，必定遭他毒药人。黑色天中年寿上，更从地阁\n似烟笼。又如黑色初发散，此个须臾命必终。眉间横入左右耳，\n百"
