   "content": "【术数全书·上册·太清神鉴·第22/22节】（公有领域原典·后周王朴·相术·Vision OCR）\n\n卦变别有图说，见启蒙。\n礼毕韬書，袭之以囊，入椟加盖，敛笔砚墨版，再焚香致\n敬而退。\n如使人筮，则主人焚香，揖筮者而退。\n代著法\n储泳曰：筮易以着，古法也。近也以钱掷爻，欲其简便，要\n不能尽卜筮之道。自若以钱之有字者为阴，无字者为阳，两手\n背为拆，二画也。两面为单，一画也。朱文分以为钱之有字者\n为面，无字者为背，凡物面皆属阳，背皆属阴，反旧法而用之。\n故建安诸学者，悉主其说，或谓古者铸金为贝，日刀、曰泉，其\n阴或纪国号，如镜阴之有款识也。一以为阴，一以为阳，未知\n孰是。大抵筮必以着，求为简便，必尽其法。余常以木为三弹\n丸，丸各六面，三面各刻三画，三面刻二画，呵而掷之，以尽\n老少阴阳之变。三丸各六面，十有八变之义也，三面为三，乾\n之九也；三面为二，坤之六也。此用九用八之义也。三者乾之\n一，画函三也，二者坤之一，画分二也，此三天两地之说也。三\n丸掷之皆三则成九，老阳数也；三丸掷之皆二则成六，老阴数\n也。两二一三则成七，少阴数也；两三一二则成八，少阴数也。\n所用者乾坤之画以成八卦，是乾坤生六子之象也。丸象太极之\n一也，三三乾，三二为坤，象两也。三丸者，象天地人之三\n才也。每丸得数十五，洛书皇极数也；合三丸之数而为四十有\n五，河图九宫数也。上二则下三，上三则下二，动静皆五，故\n五藏于用，参以四十有五数，大衍之数五十也，三丸成九于上，\n则三丸伏六于下，此老阳变阴之体也；三丸成六于上，则三丸\n伏九于下，此老阴变阳之体也。二三相对，每丸各具三五，此\n参伍以变，错综其数之皆也。体圆而转，变动不居也。六位相\n乘，周流六虚也。三丸六掷而成卦，亦十有八变之义也。既无\n钱背钱面阴阳之疑，又合老少阴阳之变，尝语同志以为然。因\n著其法与天下共之。凡得卦爻，老变少不变则为之卦。\n分卦直日之法\n孟康曰：分"
