   "content": "【术数全书·上册·太清神鉴·第21/22节】（公有领域原典·后周王朴·相术·Vision OCR）\n\n举者。考最当迁，吏民上书乞留，诏许增秩，卒于小黄。世人\n谓延寿之法，凡筮得某卦，则观其所之卦林，以占吉凶。或封\n爻不动，则但观本卦林辞爻本影有王佖者，于雍熙二年春遇异\n人，筮得观之贲林云，东行无门，西出华山，道塞于难，游子\n为患之语，最为有准。后之观者，不可不辨。延寿所著卦筮之\n书，出于阴阳家流，然当西汉中叶，去三代未远，文辞雅淡，颇\n有可观览，谨录上。\n易林杂识\n东莱费直长翁日：六十四卦变占者，王莽时建信天水焦延\n寿之所撰也。夫《易》广矣，大矣，以言乎远则不御，以言乎\n逐则静而正，以言乎天地之间则备矣。然《易》谓六十四卦也。\n推而言之，则繇说卦之所未尽，故连山归藏《周易》，皆异词而\n共卦。虽三家并行，犹举一隅耳，赣善于阴阳，复造此致易未\n见者，其射存亡吉凶，遇其事类则多中。至于糜碎小事，非其\n类则亦否矣。赣之通达隐几，圣人之一隅也，延寿独得隐士之\n说。\n前汉书京房字君明，治易事梁人焦延寿，名赣。赣贫贱好\n学，得幸于梁王，王供其资用，令极意学，既成，为郡吏察举\n补小黄令，以伺候先知奸邪，盗贼不得发，爱养吏民，化行县\n中，举最当迁。三老官属上书愿留赣，有诏许增秩留，卒于小黄。\n赣常日：得我道以亡身者，京生也。其说长于灾变，分六十卦，\n更直日用事，以风雨寒温为候，各有占验，房用之尤精。\n宣和末，长庆福崔相公任州日，其时晏清无事，思此圣书，\n虔诚自卜，得大卦云：典册法书，藏在兰台，虽遭乱溃，独不\n遇灾。之遁卦辞曰：坐席未温，忧来扣门，窬墙北走，兵来我\n后，脱于虎口。其时卜后十日州乱，崔相公窬墙而出，家族不\n损，无事归京。乃知此书贤人所制，初虽难会，后祥无不中节，\n见者当所敬重，黄金自贵，未能蒙于此书。\n绍兴末，完颜亮入寇，时有人以焦赣《易林》筮，遇解之\n大壮，其辞日：骄胡火形，造"
