   "content": "【术数全书·上册·太清神鉴·第6/22节】（公有领域原典·后周王朴·相术·Vision OCR）\n\n龙角，为显贵之位。有骨肉端美、从眉上积起涉额如龙角\n者，主为使相，女人为后妃。若形盘薄状如蚯蚓者，心多妒忌\n也。\n虎角，将帅之位，当主兵权。一名疑路，主行之象也。色\n好宜行，色恶慎出，有黑痣者行不远。\n牛角，主权贵之位。骨起如角者，使相之权。\n辅骨，乃职制之位。骨大者官职大，骨小者官职小，缺陷\n者终身无禄。\n元角，主官禄之位。骨起有角者全禄，无角者不可求官。\n釜戟，主金吾之位。骨肉起者有兵革之权。色好，武选清\n显。陷者兵死。\n华盖，主邪正之事。深厚，主寿有官。短促，刑狱少寿。浅\n薄，殃邪。一名厄门。有恶色黑痣及平落，主暴死。一名皮部，\n干枯者主经商销折。\n福堂，主福禄之事。丰厚者，有官禄，无灾，富寿。狭薄\n者贫天无官。一生又遭非横之灾。\n郊外，主出行之事。若恶色，不可远行。骨起者，一生不\n可出游。有黑痣缺陷者，他乡死。\n印堂横列八位\n家狱，主刑厄之事。平满润泽者，一生不徒囚。一名频路。\n若是常不洁者，主多忧，陷缺者狱死，\n蚕室，主女工之事。平满光静，家内宜蚕。陷缺，无田蚕。\n色恶，妻妒不良。\n林平，主仙道之位。骨肉起及色常光泽者，修道德。或急\n或恶缺陷者，服药死。\n精舍，主僧道之位。平满色泽，释慧有成。缺陷色恶者，释\n无成。\n嫔门，主宫嫔之位。丰润色好者，妻妇吉庆。缺陷者妻妇\n厄。\n劫门，主劫盗之位。骨起肉丰及色好者，永不被盗。有黑\n痣，常被劫。发恶色，劫贼。\n青路，主私路出入。色莹泽好者，出入则吉。色恶者，不\n宜出入，则有厄难。\n巷路，主公路出入。色净平者，出入则获福禄。色恶者，出\n入则有凶恶也。\n山根横列十位\n太阳，主口舌喜庆。色恶，主斗讼。有黑痣，常忧争竞。色\n好，男得好妇，女得好夫。\n中阳，主家室之事。青色，夫妻欲离。黑色，主病。赤色，\n夫妻斗竟，其色好，得暴财之吉。"
