   "content": "【术数全书·下册·淮南万毕术·第5/16节】（公有领域原典·汉刘安·杂术·Vision OCR）\n\n既雨且雾，次复二日后大雨。\n兩前雾者，至夕颓壁也。\n雨后雾者，城陷之候。\n远观十里外有青黑气者，大雨将至。\n午刻日色赤者，次后一日雨。申刻日色赤，次后二日雨。\n日入光赤，七日后雨。日始出色赤，即日雨。\n观云\n候日始出，日正中，有云覆日，而四方亦有云，黑者大雨，\n青者小雨。\n日入方雨时，观云有五色，黑赤并见者，雨即止。黄白者\n风多雨少。青黑杂者，雨随之，必滂沛流潦。\n常以戊申日，候日欲入时，日上有别云，不论大小，视四\n方黑者大雨，青者小雨。\n以丙丁辰之日，四方无云，唯汉中有云者，六中日风雨如\n常。\n以六甲日、平旦清明，东向望日始出时，如日上有直云大\n小贯日中，青者以甲乙日雨，赤者以丙丁日雨。\n白者以庚辛日雨，黑者以壬癸日雨，黄者以成己日雨。\n六甲日四方云皆合者，即雨。\n四方有跃鱼云游疾者，即日雨；游迟者，雨少难至。\n四方有云如羊猪着，兩立至。\n四方北斗中有公，后五日大雨。\n四方北斗中无云，唯河中有云，三枚相连，状如浴猪，后\n三日大兩。\n日入时有黑云相接于日，雨注即倾滴也。\n日没时云暗红者，或风或雨。\n午刻有云蔽日者，夜中大雨。\n日始出，东南有黑云，已刻雨。\n日入西北，有黑云覆日，夜半雨。•\n清晨云如海涛者，即时风雨兴也。\n云逆风行者，即兩也。\n日已出，卯刻有大云，浑者天阴，清者天雨。\n云在山下布满者，连宵细雨数日。\n云若鱼鳞，次日风最大。\n夜雨达且、盈盈不尽者，细雨还大也。\n天中有云乱扰者，风雨最多也。\n日出红云见，申刻有雨。\n兩随风乱飞无力者，要时大雾天黯也。\n日没红云见，次日雨。\n凡秋冬以东风、南风有雨，春夏以西风、北风有雨。\n讯头风不长，过后风雨愈毒也。\n夏日雨过，东风起，迟暮越大，将拔屋。\n凡候雨，以晦朔弦望、云汉四塞者，皆当雨。\n如斗牛彘者，当雨。\n暴有异云如水牛者，"
