   "content": "【术数全书·下册·淮南万毕术·第8/16节】（公有领域原典·汉刘安·杂术·Vision OCR）\n\n兹者建造屋宇，其土木泥石绘画之人，所有魇镇咒诅不出百日，\n乃使自受其殃。预先盟于群灵，则灾祸无干于我，使彼自受，而\n我家宅宁矣。造船者亦依此例。\n如梓人最忌倒用木植，必取生气，根下而梢上，其魇者倒\n用之，使人家不能长进，作事颠倒。解法以斧头击其木曰：倒\n好，倒好，住此宅内，世世温饱。\n又造前梁，临上乃移为后梁。魇日：前梁调后梁，必定先\n死娘。卯眼内放竹楔者，魇曰：枸卯放竹，不动自哭。使人家\n屋内常有哭声。\n有刻人像书咒于身，以钉钉于屋上，钉眼令瞎，钉耳令聋，\n钉口令哑，钉心令有心疾，钉门使房主不得在家，令出门钉之，\n终不得安居屋内。\n如钉床以竹丁十字钉之，或画人形纸符于内，使卧床之人\n疾病不安。此梓人魇镇之法，大略解之。\n其屋既成，用水一盆，使家人各执柳枝蘸水绕屋洒之，咒\n日：水郎、木郎，远去他方，作者自受，为者自当。所有魇镇\n与我无干，急急一如太上律令。则无患矣。\n如瓦匠所魇，有合脊中土人船伞之类，或壁中置一匙一筋，\n曰：只许住一时。其家便破。\n如甃砌门限阶基之下，用荷叶包饭于下，以筋十字安在上，\n、\n令有呕噎之疾。\n有砌灶，用木刻人以马尾吊烟囱中，火气熏之，则木人相\n撞，令夫妇相打。或有以瓦刀朝其寝或向厅堂，使有刀兵相杀。\n石匠凿人形置磉下，又画匠绘画梁栋皆有魇咒，不可不知，\n知之则无害矣。\n凡梓人造作魇镇咒诅者，必以墨签插在首，勿令插之则不\n灵。\n土牛经\n目\n录\n释春牛颜色第⋯⋯\n释策牛人衣服第二………\n释策牛人前后第三⋯…•••⋯•⋯⋯⋯⋯⋯⋯•\n⋯⋯⋯•（554）\n（554）\n（555）\n（555）\n术数金书下卷\n释春牛颜色第一\n常以岁干色为头。从甲乙两丁戊已庚辛壬癸为十干。\n甲乙木其色青，两丁火其色赤，戊已土其色黄，庚辛金其\n色白，壬癸水其色黑。余仿此。\n支为身色"
