   "content": "【术数全书·下册·淮南万毕术·第6/16节】（公有领域原典·汉刘安·杂术·Vision OCR）\n\n时止。甲寅雨，立时止。乙卯雨，一日止。丙辰雨，一日止。丁\n已雨，即时止。戊午雨，立止。已未雨，即时止。庚申雨，四\n日止。辛西雨，即日止。壬戌雨，即时止。癸亥雨，立止。半\n天云雾见日在洞中，雨止，天遂晴。\n祷雨\n冬春夏秋四时之首甲子日，不宜雨，雨必旱在六十日后。以\n此之时请雨，则用垒土为龙，使二童舞之入山。如此数日，则\n天降甘霖也。故淮南曰：土龙致雨。\n凡少年妇女仰天大号泣不语，则雨降。\n《神农求雨书》曰：春夏雨日而不雨，甲乙命为青龙，又为\n火龙，东方小童舞之。丙丁不雨，命为赤龙，南方壮者舞之。皮\n己不雨，命为黄龙，壮者舞之。庚辛不雨，命为白龙，又为火\n龙，西方老人舞之。壬癸不雨，命为黑龙，北方老人舞之。如\n此不雨，遂潜处，阖南门，置水其外。开北门，取人骨埋之。如\n此不雨，命祝巫而暴之。暴之不雨，神山积薪，击鼓而焚之。\n祈\n晴\n兩久急欲止者，取铜瓶著四五斗沸汤，绵絮固口，入井。声\n振数十里，则雨止。但旱五十日耳。\n大潦欲止者，使三寡妇、七孤儿持捣米杵，孤儿仰天号，寡\n妇伏地哭，则雨立时而止也。以下阙七条。\n•\n•相雨书\n右《相雨书》十篇。候气者三十，观云者五十有二，察日\n月并宿星者三十有一，会风者四，详声者七，推时者十二，杂\n观者十四，候雨止天晴者七，祷雨者三，祈晴者九，共为百六\n十有九，皆有准验。为唐人黄子发所著。夫唐三百年间，论天\n文者寥寥可数，况卜阴晴于俄顷、辨风雨于一时乎？历朝以来，\n惟汉东方曼倩著《风雨书》一卷：京房著占一卷。讫今不传，固\n可惜也。嗣后七八百年之间绝而不彰，即淳风天纲天文之士所\n著亦不过占星候气而已，未尝究竟于风雨也。夫风雨之候有关\n于国者最大，军期祭日率有所资。下至野老农夫，无不秉来而\n观晴雨。是以旷代不闻者，或恐占之而不验，或疑五行之不详，\n而不知"
