   "content": "【术数全书·下册·淮南万毕术·第3/16节】（公有领域原典·汉刘安·杂术·Vision OCR）\n\n百三十六。取鸡血与针磨捣之•以和磁石，用涂棋头，嗓干之，\n置局上，即相拒不休。九百八十八。取鸡血杂磨针铁，捣和磁\n石，棋头置局上，自相抵击。史封禅书索引。案《史记•绛侯\n周勃世家》：太后以冒絮提文帝。索隐引肖该《汉书音义》云：\n“提音底，提者掷也。提有底音，掷与投义合。孙本作抵棋，因\n俗本误改。又今校宋本《御览》九百八十八，引万毕注字多讹\n脱。愚按史孝武本纪正义，引高诱注准南云云，正谓此事，语\n并同。今悉依改正。\n盐能累卵。《御览》八百六十五、九百二十八。取戎盐涂卵，\n取他卵置其上，即累也。同上。\n艾火令鸡子飞。《御览》七百三十六、九百二十八。取鸡子\n壳然艾火，内空中，疾风高举，自飞去。七百三十六。取鸡子\n去其汁，然艾火，纳空卵中，疾风因举之飞。九百二十八。\n首泽浮针。《御览》七百三十六。取头中垢，以涂塞其孔，\n置水即浮。同上。\n胶挠水则清。同上。\n弊箕止咸。同上。取箕以纳酱中，咸著箕矣。同上。\n鸿毛之囊，可以疲江。《御览》七百四、九百十六。盛鸿毛\n满囊，可渡江不溺也。七百四。盛鸿毛于缣囊，可以渡江不溺\n也。九百十六。\n鸠颈血涂鸡头，不能起。《御览》七百三十六。\n鸱脑令鸡自伏。《御览》九百二十三。孙本未采入，今增。\n取鸱脑以涂鸡，即自伏不能起也。同上，并增。\n寒皋断舌，使语。《御览》九百二十三。取寒皋断其舌，即\n语矣。寒皋一名鸲鹆。同上。孙本脱首一句，今增。\n乾睾一名鹦鹉，断舌，可使言语，《艺文类聚》九十一，孙\n本未采入，今增。\n伯劳守金，人不敢取。《御览》九百二十三。孙本未采入，\n今增。取伯劳血徐金，人不敢取也。同上，并增。取伯劳血涂\n金，人不取，化为石也。《御览》七百三十六。\n伯劳使蛇蜿蝉。《御览》九百二十三，孙本未采入，今增。\n乃天使然也。同上，并增。案蜿蝉，盘曲貌，王"
