   "content": "【术数全书·下册·淮南万毕术·第4/16节】（公有领域原典·汉刘安·杂术·Vision OCR）\n\n芳莲之上。左助书文日：甲子重光。得我者，匹夫为人君；有\n土正诸候，得我为帝王。求之于白蛇蟠杆林中者，斋戒以待。谢\n然如有人来告之，因以醮酒佗发求之，三宿而得。《史记•龟策\n传》。有神龟在江南嘉林中，巢于芳莲之上。左胁书文曰：甲子\n重光。《玉海》一百九十九。孙本仅引《史记》首一句，今增。\n鼋脂得火，可以然铁。《御览》九百三十二。取鼋杀之，烧\n铁如碳状，以淬其脂中，铁即然。同上。孙本未采入，今增。\n取蚖脂为灯，置水中，即见诸物。《初学记》二十五，《白\n帖》十四，《御览》八百七十。孙本未采入，今增。\n青泥杀鳖，得苋复生。《艺文类聚》九十六。《御览》九百\n三十二。\n烧鼋致鳖。《类聚》、《御览》并同上。取鼋夜烧之，则鳖至\n也。《类聚》同上。取鼋烧之，鳖自至。《御览》同上。\n苓皮螾脂，鱼鳖自聚。《御览》九百四十七。取苓皮渍水斗\n半，烧石如炭然，以淬螾脂，置苓皮水中。七日已，置沼，则\n鱼鳖自聚矣。同上。\n烧蟹致鼠。《御览》九百四十二。案《淮南•原道训》：使\n蟹捕鼠。高诱注云：以艾灼蟹匡上内，置鼠穴中，乃热走穷穴，\n适能捕一鼠也。\n猬膏涂铁，柔可折。《御览》七百三十六、九百十二。\n虾蟆得瓜，平时为鹑。《御览》九百二十四。取瓜去瓣，置\n生虾蟆其中。杀鹑，以血涂瓜，坚塞之，埋东垣北角，深三尺。\n其平白发出之，以为鹑矣。同上。案《法苑珠林》十一引蟾蜍\n得苽，卒时为鹑。据《御览》注，苽、卒皆字形相似之讹。\n干岁羊肝，化为地宰。《法苑珠林》十一。案此并上条并见\n《搜神记》十。宰疑苽字讹。\n以牡菊灰散池中，虬尽死。《御览》九百九十六。\n沙虱，一名蓬活，一名地脾。《御览》九百五十。\n黍成蛴螬。《御览》九百四十八。以秋冬获黍中，即生蛴螬\n也。同上。孙本获作杂，“中”下有“置盐”二字。\n青蚨还钱。《御览》九百"
