   "content": "【乙巳占·乙巳占·OCR第38/56节】（公有领域原典·唐李淳风·星占）\n\n中，汉起兵以卫京师。刘向日：吴楚七国反。国皇，巫咸曰：\n国皇之大而赤，类南极老人也。《春秋考异邮》曰：国皇见东南，\n则兵起，天下急。司马彪《天文志》日：孝灵光和中，国皇\n见东南角，去地一二丈，如炬火状，十余日不见。占日：国皇\n为乱，内外有兵丧，其后黄巾贼张角烧州郡，朝廷遣将讨平，斩\n首十余万级。蚩尤旗。河图荧惑之精，流为蚩尤旗，类彗而后委\n曲，象旗也。《说苑》目：蚩尤旗，五星盈缩之所生。夏氏日\n“四望无云，独见赤云，蚩尤旗也。黄帝占日：蚩尤旗，本类\n彗而后委曲，象旗幡，长可二三丈。见则王者旗鼓大行，征伐\n四方，兵大起。不然，国有大丧，期三年，中五年，远七年，\n魏高贵乡公元年，有白气出南北侧，广数丈竟天。王肃曰：畫\n尤旗也，东方有乱乎？后母丘俭据淮南以叛。\n《春秋运斗\n枢》曰：蚩尤旗干太微法灭，帝死于野。天谗占。甘氏曰：天\n谗在西南，长数丈，左右锐，出而易处。京房目：天谗出其\n下，相谗为兵，赤地千里，枯骨籍籍。《汉书•天文志》日：天\n谗为天丧，一云兵丧。旬始。《说苑》日：旬始，五星盈缩之所生\n也。巫咸日：旬始出于北斗旁，状如雄鸡，其怒有青黑，象伏\n鳖。《春秋合诚图》日：黄彗分为始，为立王之题。主乱\n主招横，见则臣乱兵作，诸侯虐，期十年，圣人起伐，群猾横\n恣。《春秋考异邮》日：旬始照其下，必有灭王。《汉天\n文志》日：旬始如鳖，一见群猾横恣。•玄冥占日：有如雄鸡，\n其色赤黄，其名日旬始，则天下有兵，其国不宁，期三年。\n天狗。黄帝占日：天狗者，五星之气，出西南，金火气合，名\n日天狗。孟康日：天狗有尾，旁有短彗，下有如狗下食血，其\n军必败。石氏日：西北有星，长三丈而出，水金气交，名日天\n狗，见则大兵起，天下大饥，人相食。石氏曰：夫天狗所下之\n处，必有大战，破军杀将，伏尸流血，天狗食之。皆期一年，中\n二年，远三"
