   "content": "【乙巳占·乙巳占·OCR第29/56节】（公有领域原典·唐李淳风·星占）\n\n近不战。太白出未高，敌深入者可敌，去勿追。太白出高，敌\n深入境，勿与战，去亦勿追。太白入西方，未出东方。东方南\n方起兵者，胜得地。其后主败将死。太白入东方，未出西方，北\n方兵起者，身死亡地。太自主秦国，主雍凉二州。太白大，秦\n晋国与王者，兵强得地，王天下。太白赤角则兵战，白角兵起，\n黑角兵罢，青角忧。太白圆有丧，芒角，隋芒所指，兵之所起。\n太白昼见，为兵丧，为不臣更王，强国弱，弱国强。太白昼见，\n亦为大秦国强，各以其宿占，其国有兵。太白犯五星，有大兵；\n犯列宿，为小兵。太白犯荧惑，为大战。太白在南，南国败；在\n北，北国败。魏青龙二年五月丁亥，太白昼见，积三十余日，以\n暑度推之，非秦、魏，则楚也。是时诸候使诸葛亮据渭南，与\n司马懿相持，孙权寇合肥，又遺陆机孙皓等入淮。帝亲东征，蜀\n本秦地，则为秦魏及楚兵俱起。月与太白相犯，人君死，又为\n兵。太白当见不见，是谓失舍。不有破军，必有死王篡其国。宋\n志云晋威宁四年，太白应见不见，至青龙五年十一月，羊祜伐\n吴，太白始夕见西方，而卒灭吴。当见不见之应。\n太白人列宿占第三十五\n角。太白犯左角，大战不胜，将军死。金守角一尺，十六\n日，太子骄溢，国都围，大人自将兵于野，民多疾疫，\n金守角为兵。其守色黄。大臣益地。色赤臣欲反其主。金\n乚巳占\n逆行左角间有刺客天子慎之。金守左角，群臣有谋不成，有其\n家坐罪。亢。金入亢，中国有兵。若行疾犯凌而有芒角，朝廷\n贵臣有戮者，一百日，远八月。金星数入亢，其国疾疫。金守\n角亢为兵，大人自将兵于野。金守亢，收敛用兵，以备北方。金\n逆行犯亢，为兵逆臣乱，人君有忧。氐。太白犯氐左星，左中\n郎将诛死；犯右星，右中郎将诛死，期三年。又云：五星犯左\n右星数。金同用。金入氐，天下大疫。一日有兵。金守五星，同\n守之，加兵其国。房。•金入房成勾，为天子"
