   "content": "【乙巳占·乙巳占·OCR第16/56节】（公有领域原典·唐李淳风·星占）\n\n名鸟帑。《史记•天官书》日：翼轸，荆州也。今之南郡、泰置。江陵、江\n夏、汉高帝置，零陵、郡，汉武帝置之。桂阳、武陵、二郡、汉高帝置。长\n沙、郡、秦为郡，汉高帝改为国。汲、汉中、秦置。汝南，汉高帝置。皆\n楚之分也。周成王时，封文王之先师鬻熊之曾孙绎于荆蛮，为楚\n子，居丹阳。后十余世至熊通，号武王，浸以强大。后五世至庄王，\n总帅诸侯，观兵周室，并吞江汉之间，内灭陈鲁之国。后十余世，\n有项王，东徙于陈焉。《楚世家》日：𩱳熊，祝融之苗裔也，姓芈氏，\n居丹阳，今南郡枝江县是也。武王子文王始都郢，江陵是也。庄\n王曾孙昭王，为吴所破，吴兵入郢。昭王出奔随，使楚大夫申包\n请救于秦，秦乃救楚，大败吴师。阖庐弟夫概，返吴自立为王，阖\n庐闻之班师。昭王乃得返国，更都于鄀。都，南郡都县是也。属\n荆州。《尚书•禹贡》日：荆及衡阳唯荆州。《周官》日：正南日荆州，《尔雅》\n日：汉南日荆州，自汉南至衡山之阳。未央《分野》日：楚治郢，南至九江，北\n至积水，东至海，西至鱼腹山。今为汝南、汝阳、庐江、豫章、长沙、南海，故\n楚治南郢者也。《周礼》大司徒职云：以土圭之法，辩十有二土之\n名，以相民宅而知厉害。郑玄云：十二土分野十二邦，上系十二次焉。保\n章氏云：星辩九州之地，所封之地，皆有分星，以视袄祥。马融云：\n星，土也，星所主也。土地传日：参主晋，商主大火也。辩，别也。封，界也。\n封域一国也。分星自斗十二度，谓之星纪之饮、吴越之分野之类也。冯相\n氏掌十有二岁、十有二月、十有二辰、二十八宿之位，辨序其事，\n以会天位。位，大岁。岁星与日月同次之月，斗在建之辰。\n《诗纬•推度灾》：\n已占\n邶国，结蝓之宿。宋均曰：谓营室星。\n鄘国，天汉之宿。天津也。\n卫国，天宿斗争衡。国分所宜。\n王国，天宿箕斗。\n郑国，天宿斗衡。\n魏国，天宿牵牛。\n唐国，天宿奎娄"
