   "content": "【乙巳占·乙巳占·OCR第7/56节】（公有领域原典·唐李淳风·星占）\n\n无军在外而有此气，天子失御，人民多叛。日月皆晕，共战不\n合兵罢。日以庚子晕，有赦令。日有青晕，不出旬日有大\n风，籴贵，人民多为病凶。\n日有黑晕，灾在用事之臣。日\n晕七日无风雨，兵大作。不可起兵，众大败。\n日晕而珥，宫\n中多事，后宫忿争。七日不雨、审察官中。日晕而珥，立侯王，\n人有谋。军在外，外军有悔。日晕且珥如井斡，国亡以兵乱\n大战。一珥为一国兵战，二珥为二国兵战，以珥为数，日晕珥，\n贵人有罢，国有谋反，亦为拜将。十二日负气。负气者，青\n赤如小半晕状，而在日上则为负，负者得地为喜。日重晕四\n负，殃大如内乱，三日雨不占。\n戟气者，青赤气长而斜倚日\n旁，为战戈戟相伤之象。日晕且有冠，且有戴，天下立侯王。\n若自立者，其分必有益土。日晕而有戴，若拜谒、立诸侯，德\n令矣。日晕有抱，抱为顺，日月之旁，王者有喜，子孙吉昌，\n政令行。两军相当，有抱者胜。\n日晕抱珥，上将易。日晕而\n背，兵起，其分失城，背焉，逆有降反城。背在东，东有叛；在\n西，西有叛。他仿此。盖两军相当，背所在方败，无背者胜。背\n者逆也。\n日晕中有璚为不顺，与背同。人臣不忠，为外其心，君臣\n乖离。其国兵起，若有逃臣。\n日晕而玦，两军相当，所临者\n败。内外同，军玦战。日晕而有直气在两旁，其国有自立诸\n侯王者，封赏左右。两军相当，有直者胜。\n日晕四提，必有\n大将出亡。日晕而有背，抱珥直而虹贯之，宜从虹而击之。\n日晕有背者，有军不合战，将有叛。内外同，在内为内，在外\n为外。两军相当，日晕而冠珥及缨者，军和解。抱戴者有喜。\n日月无精光，青赤晕，虹蜺背玦在心度中，是谓大荡。兵丧并\n起，当以赦除之咎。日晕而珥，有云穿之者，天下名士死。\n日晕而两珥右外，有聚云在中与外，不出三日，城围出战。\n日月晕，仰视之，顺臾当有云气从旁入者，急随云以攻之，大\n胜。 日晕有聚云不出"
