   "content": "【乙巳占·乙巳占·OCR第23/56节】（公有领域原典·唐李淳风·星占）\n\n井。木入东井，主秦国，留守之，以仁致天下。木犯东井，\n人主有行仇水之事，大将恶之，其国内乱，有兵起。木犯井钺，\n刑罚用，兵起。木乘守东井，人主有法令水术之事，逆臣为乱，\n将军死，人君有忧。\n鬼。木犯鬼，人君有忧，斧用，大臣诛。木入鬼，留\n十日已上，令散于诸候，期六十日，若十月。木逆行抵与鬼中\n央者，其君主之。木守鬼，为大人有祭礼之事。木守鬼，出于\n左右，贵亲坐之。木守与鬼西南，为秦汉有反臣，以赦令解之。\n木干犯守天尸，国有丧。天尸，鬼中粉白者是。\n柳。木犯柳者，有木功事，若名木见伐者。木经柳，国多\n义兵。木守柳，贵臣得地，有德令，不出九十日。木逆守柳，为\n反臣，中外兵 起，以德令解之。\n星。木入七星，有君置太子者。木留七星，为天下大忧。木\n守七星，多火旱，万物五谷不成，有兵饥。木入若守七星，盗\n贼有兵。\n张。木入张，旱多火灾，万物百谷不成。木逆行张，其君\n用乐淫洗。木处张西，岁大水，东为大旱。木守张，天子有庆\n贺事。木守张十日，其岁大丰，五谷成，三十日不下，天下安\n宁，守之留百日，其主升平，君臣同心。木逆行守张，人民疾\n疫，多心腹病。木犯张，若守之，王者政事，若有干里之行。\n翼。木入冀，人多死流亡，五谷伤于风，期一岁中。木出\n入留舍翼，荆楚有急，岁多大虫，六十日不下，小人失功。木\n守翼，王者应天，又方术之士大用，翼辅正政，天下符瑞，不\n出九十日。木守翼，主圣，天下和，五谷登，人民乐，礼义兴。\n轸。木入轸中，伺其出日而数之。期二十日，皆为兵发，伺\n始入处数之，率一日，期十日，军罢。二十八宿中外官，同有\n此占。木逆行至轸，及守之，其国有丧，人君改服，天下更主\n之令，期二年，王者以赦除害。一日所舍七日不移，有杀君者。\n木逆行至轸，及守之，其国有丧人君者。木在轸，王者忧疾病，\n若有丧，不出九十日改服，王者修"
