   "content": "【乙巳占·乙巳占·OCR第54/56节】（公有领域原典·唐李淳风·星占）\n\n则三公受贺，以座处推之。\n假令大风从丑上来，大寒迅急，君有暴令，知止何座，其\n座自当之。假令大风折木，从臣座上来，止于君者，此臣上书\n奏事于君也。宽大温和为贺。假令廉贞宽大公正之日，其日清\n明温和，风从臣座上来，止于君者，此臣忠正，必受贺赐。假\n令官日宽大，时加官，此近贵相客也。四十里内风半日止者，五\n十里贵客也。一日止君者，百里内也。二日止者，干里大客也。\n风三日止君者，外台使者也。四日止君者，外州使者。五日止\n君，边将使也。七日止君者，此四万里夷狄使也。风冥冥寒急，\n此远方使至，非顺气也，必怀叛逆。其风气来时，日加已酉丑\n戌午，此为正臣欲贡献于中国也。风以远近迟疾清温为吉。寒\n迅为忧。假令风从宫上来寒急，君欲行诛也；温和兩者，欲知\n位赐也。占贵客，自天子已下至于庶人，其占皆同下臣贵客。同\n巴占\n大国小国家人差次，四季受官日，风从四季上来，止君若子，皆\n为客候主人，期一日九日。假令官情合君臣相会。\n候大兵攻城并胜负候贼占第九十八\n假令角日大风折木，从申子亥卯上来，大寒过度。以日中\n夜半，其风益怒，比连三日至七日，此兵且乘攻城邑必下，主\n人宜出城邑避之。古所以然者。夜半日中，子午也。纯宫，土\n也。角木克土，春夏克土之时，攻城必陷也。此日宜为客，不\n宜为主人，土畏于木，主人必弱败，近期九日，中期二十七日，\n远期七十日。假令诸商羽之日，大风折木，从商上来，此兵且\n来围城邑。日中夜半，其风益怒，此攻城不能下，客必败。所\n以然者，商金羽水，母子为强，水畏于土，势不能行，土必制\n水。日中夜半，城中强，可以外固守，客军自丧。公正之日，风\n从公正上来，止宽大上，为长吏胜贼。阴贼之日，时加公正，风\n从阴賊上来，止奸邪，为贼胜吏败也。候水中贼，常以壬子、壬\n成、壬申、壬辰之日，有风从子上来，三日已上，日光不明，此\n水"
