   "content": "【乙巳占·乙巳占·OCR第44/56节】（公有领域原典·唐李淳风·星占）\n\n市中，神奇物出，天子有喜。赤气出天江，车骑将军出。苍白\n气出河鼓中，将有忧。黑气入匏瓜，天子食果为害。苍白气入\n天津中，君有水忧。苍黑气入王良，奉车忧。苍白气入附路，太\n仆忧。客气出天船中，不出一年有自立者。苍白云气入三台，人\n民多丧。白云大围长二三丈，出天牢中，贵人及人亲属，必斩\n死；赤气入天理中，兵大起。赤气出东西掖门者，起兵将受令。\n赤气入东西掖门，内乱兵起，人主且有吉事，天必应以云光影。\n黄白气人东西掖门，天子有喜。黄白气出东西门，天子出德令。\n一日：云如为口在太微中，有人为外应者。黑气入东西披门，大\n人忧。苍白气出东西掖门，天子忧丧事；出太微中，其祸除。苍\n白气如人反走兽、入太微坐旁有反者。苍白气如走兽、入抵太\n微帝座星，天子有忧。苍白气入抵太微及帝座，天子有丧事。赤\n黄气润泽入太微中，天子有喜事。赤黄气润泽如箕帚入太微中，\n妇女有喜事。赤黄气如箕帚出太微中，天子用钱物赐美女。赤\n黄气入太微中，天子用钱赐诸候王。赤气出太微，兵起。一日\n有立王。赤气如杯碗正圆、出太微中，天子用壁赐诸候王。赤\n气直指太微坐左右，诸侯且内乱。黄白气出太微中，有立王。黄\n白气如赤黑气、蛟蛇及龙形、在太微庭宫阙上，有白衣之会，其\n同章环太微天庭而主杀主丧。此气皆乱臣谗贼之气。黄白云气\n出官上，若旗有光，人主有喜，延年益寿；有青白气出五帝座、\n径出南门者，不出九十日，人君失其官，天下不安。赤气出五\n帝座、下至入幸臣中者，不出六十日，近臣有欲谋其君者。气\n不成、不明形者，死亡，天下大乱。青白气出幸臣、入五帝座，\n臣中正欲论兵事发。入积卒同占。气上赤下白，大如井口，从外\n入压太微庭者，邪臣；气直者，贵臣之气。太微中有云如鸟，诸\n侯反，有来诛天子内连谋。黄气出太子座上、入五帝座者，不\n出六十日，太子即位。黑气抵太微坐，左右"
