   "content": "【乙巳占·乙巳占·OCR第10/56节】（公有领域原典·唐李淳风·星占）\n\n其国相死。出心太北，国旱，宗庙灾。出心太南，君忧，且有\n兵起。月变于心，人主有忧，兵在外，大将易。无兵，太子事，\n亦为天子计失于刑罚。尾。月犯尾，贵戚有诛者，其国将军\n死。月在尾，后官有争，人君子孙不吉。箕。月入箕，籴大\n贵，天下旱，饥死过半，人君号令伤于酷暴，百姓失所。月在\n箕，后官政教失，女主乖怨。有暴风失行于箕者大风。南斗。\n月行于南斗，大臣诛，大将及近臣去，将军死，女主凶。宋书志\n乚巳占\n称：晋哀帝兴宁三年七月庚成，月犯斗。来年五月戊寅，皇后瘐氏崩。安\n帝义際元年三月已巳，月掩斗第五星，至八月两成，频掩之。是年三月始\n兴木守徐道覆反。四月，卢循起湘中。五月，循破刈稯。自是京畿大臣多\n戮死也。月入斗魁，大人忧，太子辱，宫中有贼。月一岁三入南\n斗，有德令，有兵起。月在斗有变，易相，爵禄失，大臣有忧\n刑戮，及将相非理食禄，更易天子法令者。月乘斗，色恶，苍\n芒，丞相死。月宿斗，为风雨。月蚀斗，群臣忧国乱。牵牛。\n月犯牛，牛疫，牛马羊暴贵，牺牲之官有忧，将军奔道路，关\n梁阻，天下有诈，谷大贵，大国有忧，将军死。一日牛多病，月\n在牛有变，关梁闭塞，将有农令牺牲之事，四足虫疾矣。月乘\n牛，有大水，人相弃于道。须女。月犯女，女子凶忧疾患女\n惑之事，其国有忧，将军死。晋孝武大元二年八月辰，月入女。八\n月，征西将军桓豁率。十月乙未犯女，壬寅，尚书令王彪之卒也。有改\n易高下贵贱，女工兴，有女令。月在女有变，有兵不战而降。又\n日嫁女娶妇之事，亦为女主布帛。虚。月犯虚，天下大虚，虚\n邑复盛，天下政乱，国有忧，将军死，百姓饥，哭泣不已，有\n陵庙事也。月蚀虚危，人多去其室，有大战。月变于虚，有土\n功在外，军人饥。危。月蚀危。不有崩主，必有大臣丧，天\n下改服，将有坟墓哭泣之事。月犯危，治台楼盖屋者多，天下，\n乱，将军死。月"
