   "content": "【乙巳占·乙巳占·OCR第50/56节】（公有领域原典·唐李淳风·星占）\n\n物。正月旦，王者以占四时之始。风从乾来，西北方也，有小\n雨，兵起戎狄，胡兵也。风从正北坎方来，多水大雨。风从东\n北艮方来，丰稔。风从正东来，大水。风从东南来，民有疾病。\n风从南来为大旱。风从西南来者，小旱。风从正西来者，有兵\n灾。若风势大急恶昏浊，亦以八卦暴风例占之为妙也。立春正\n月节，清明少云，善熟；雾则旱虫伤禾豆，乾上风来，暴霜杀\n物，五日，粟卒贵。坎上风来，冬大风寒，北狄侵.艮上风来，\n五谷熟。震上风来，气泄，物不成。巽上风来，多风足虫。离\n上风来，早伤生物。坤上风来，春寒，六月水，人多愁土功。兑\n上风来，旱霜兵起。春风、二月中气，东方有青云，必熟；晴\n明物不成。乾上风来，岁多寒，金铁倍贵。坎上风来，菽豆不\n成，饥疫。艮上风来，夏不熟，米贵一倍。震上风来，五谷成，\n亦无贼。巽上风来，虫生，四月多暴寒。离上风来，五月先水\n后旱。坤上风来，小水，人多疟疫。兑上风来，有兵，春寒，八\n月国忧也。立夏，南方有赤云则丰，晴明则旱。乾上风来，其\n年凶饥，夏霜，麦不刈。坎上风来，多雨，鱼行人道。艮上风\n来，山崩地动，人疫。震上风来，雷动非时击物。巽上风来，其\n年丰熟。离上风来，夏旱禾熟。坤上风来，不共力万物天伤。兑\n上风来，蝗虫大动。夏至，南方赤气则熟，晴明则旱。乾上风\n来，寒气万物。坎上风来，寒暑不时，夏月多寒。艮上风来，山\n水暴出。震上风来，八月人多疾。巽上风来，九月风落众物。离\n上风来，五谷熟。坤上风来，六月多雨水横流。兑上风来，秋\n多雨霜也。立秋，有白云及小雨则吉，晴明物不成。乾上风来，\n甚寒多雨。坎上风来，冬雾多雪寒。艮上风来，秋气不和。震\n上风来，秋多雨雹，人不知草木再荣。巽上风来，卒兵内起。离\n上风来，兵戎不利，多旱。坤上风来，五谷成熟。兑上风来，兵\n起将行。秋分，西方有白云熱；晴明物不成。乾上"
