   "content": "【乙巳占·乙巳占·OCR第31/56节】（公有领域原典·唐李淳风·星占）\n\n国病疫。水守亢者，国有忧，天下大乱。水守亢，逆行不顺，其\n色明大，政未行。水逆行守，为中兵。一云：五星守亢为中兵。氐。\n水入氐，贵臣暴忧，法官有狱事。水乘氐右星，天下有大水大\n兵；乘氏右星，天子有自将兵于地野外。房。水入房十日，成\n句已，为大人恶之，以赦解之。水守房，天下水火起，不则有\n兵。水守房，为胡兵发。水守房，有白衣之会。心。水守心，以\n水灭火，三日不去，主服药酒，忠臣相戮，山川大溃，水溢滂\n滂。水守心，大水滂滂，天下失纲。水守心，为火，时多盗贼，\n人民相恶。水守心，天下大败，易主姓氏。水守心，大臣戮主，\n水逆留犯守乘凌心，王者起，内贼乱，臣下有谋易位天子者，权\n宗室得势大臣。尾。水入尾，天下大水，江河决溢，鱼盐贵三\n倍。水入尾天江，天下水。水守尾箕，后宫有省罢者。一日：后\n宫有罪者。水守尾，大饥，人相食，民异其国，君子卖子妃，后\n乱。箕。水入箕，天下大赦。水入箕，大人当之。水守箕，若\n动角芒，贵者有弃，自相灭。水守箕，七日以内祸灾起，若有\n疾风解之，消。南斗。水入南斗中，大臣诛。一曰：不用兵众\n而有天下。水守斗，有兵，赤而角，天下败；白而大，裂地，相\n贿赂为利；异而小其国亡。水守斗有兵，易政改朔。水留南斗\n所守之国当诛。牵牛。水入牛五谷不成。水守牛，水涌为败久，\n牛多死。水守牛，臣谋其上。水常以冬朝于牛当朝不朝，名目\n失律；二时不朝，名日失政；三时不朝，名日五谷不登。女。水\n入须女守之，其国当娶妇嫁女事，若他国来进女者。水守女，为\n万物不行。水守女，为后夫人有变，妾立。水守女，女主御世，\n天下大赦，其国水，国大乱。虚。水犯虚其邦多水灾。水守虚，\n政令急，天下大乱，天下虚，大人忧。水守虚，若角动青色，臣\n有斯君者，有兵丧于国内。水守虚，有女灾，丁壮行徭，妻子\n独居，万民坐虚。危。水守入危，奸臣"
