   "content": "【乙巳占·乙巳占·OCR第9/56节】（公有领域原典·唐李淳风·星占）\n\n为臣，日为君，臣以明续君，当在其时，不可与君争力竞能。昼\n明者，此奸邪并作，不救，则失其行而必毁矣。其救也，出退\n强臣，断绝奸佞，近忠直，亲贤良，则月得其行，不专明矣。是\n故人君宰相不从四时行令，刑罚不中，大臣奸谋，黜贤蔽能，则\n日月无光而见瑕谪矣。不救其行，五谷不成，六畜不产，人民\n上下不从，盗贼并起。月出非出所，行非其路，皆女主失行，奸\n通内外阴谋，小国兵强，中国民饥，下欲僭权矣。月生正偃，\n天下有兵，合无兵，人主凶。月行急，未当中而中，未当望而\n望，皆为急。兵大战，军破将死，大臣执政逼君，主将有女主\n擅权，天下乱，易宗庙。月未当缺而缺，大臣灭，女主黜，诸\n侯世家绝。月再中，帝王穷。 月当出而不出，有阴谋，有\n死王，天下乱。 月未当上弦而弦，国兵起；未当下弦而弦，臣\n下多奸诈。当盈而不盈，君侵臣，则大旱之灾。未当盈而盈，臣\n欺君，有兵。月初生而盛，女主持政。大月八日，小月七日，昏\n中过度，有兵事，如不及度，丧事。月生五日，而昏中已后盛，\n君无威德，佞臣执权柄，民背君，尊其臣。月前望西缺，后望\n东缺，名反月，臣不奉法制度，侵夺主势，无救，为涌水，兵\n起。其救也，止刑罚，诛好猾，任贤而稽疑，定谋事成，则月变不为伤亡\n也。 月当晦而不尽，所宿国亡地。月初生小而形广大者，有水\n灾。 月大而体小者旱，有气色非常，皆为皇后阴谋事。月\n始生有黑云贯月，名激云。或一或二，或三或四，不出三日，有\n暴雨。 月上有黄芒，君福昌，皇后喜。月生刺，是谓贼臣\n生中国。月生牙齿，女主后妃乱，天下兵起。月生爪牙，人\n主赏罚不行。一占云：人君左右，宜防刺客。月望而中蟾光\n不见者，所宿之国山川大水，城陷民流，亦为女主宫中不安。\n月出复没，天下乱。月分为两道，无道之君失天下。月坠\n于天，有道之臣亡。月出子地中，庶民出为王。两月并出\n相"
