   "content": "【乙巳占·乙巳占·OCR第18/56节】（公有领域原典·唐李淳风·星占）\n\n为政以德，譬如北辰，居其所，而众星拱之。又且圣人观象，分配\n国野，或取水土所生，或视风气所宜，因系之以成形象之应，故昴\n为旄头被发之象。青丘蛮夷，文身之国。梗河胡骑，负戈之俗。胡\n人事天，以昴星为主；越人伺察，以斗牛辦祥。秦人占狼弧，齐观\n虚危，各是其国，自所宗奉。是以圣人因其情性所感而属，岂越理\n苟且而傅会者哉？\n占例第十六\n按景纬垂变，妖孛示应，深浅之迹既殊，利害之差不一。先哲\n考验多有异同，得失混淆，是非重叠，不为体例，学者致疑。今则\n录薄蚀守犯，逆顺斗凌，以次相从列之云尔。日月则有蚀，有薄，\n有斗，有昏，有冥。星月同光，星月相蚀。列宿五纬则有变动。\n芒角喜怒，大小存亡。列坐官位，则有疏拆舍集；五纬袄客，则有\n逆顺迟疾。平行出入，合会聚从，离徙盈缩，金宿居。留经守天中，\n乘犯侵凌，抵触经历，贯刺磨靡掩斗，周环绕戴，句已牝牡焉。\n日月两体相掩映，从一边起渐侵，或多或少，此为蚀也，犹似虫蚀\n叶之状。 日被月蚀，阴侵阳，下凌上，咎在君王。蚀少半灾轻，\n蚀大半灾重。蚀既，亡国杀君之象。月蚀者，被日映而损元明，\n咎在女主。破大军，杀大将，蚀少半灾轻，大半灾重。蚀既，诸侯\n大臣亡国破家，女主黜退。有交为蚀，朔望依度是也。无交为薄，\n或近望朔。阴气侵迫，黄赤无光，匿气薄日也。日薄下凌上，\n强臣以迫其主，而夺其威权之象也。灾轻于日蚀。月蚀薄，为\n女主忧，大臣失其所理，蔽退之象。志云：凡军行而遇日月薄，当\n收军。不尔，有谋反。日月斗者，别有假象，共日体相凌，离而\n复合，合而复离。日月失光，乍明乍暗。或乌体具见，在乎食时以\n前。晚脯已复者为斗，斗者两竞之象，天子失据，四夷迭侵，兵贼\n俱起，击贼将兴之象。或有五色，色无主数十日，似日象为阵而\n来。口灾日者，大凶灾重，亡国杀君之象。此灾尤于日蚀昼昏者，\n日无云而光暗。"
