   "content": "【乙巳占·乙巳占·OCR第27/56节】（公有领域原典·唐李淳风·星占）\n\n死王，客水至，小兵。斗。填星乱行人斗，且失地使之。不然，\n无淫于乐，无见诸侯客，无所出游，如此即止。又日：入天库，\n以丧起兵国中。土逆行斗，地动。土犯斗，先水后旱，若守之\n一旬，名水有溢者。不然，则有暴水出。土守斗，国多义士。土\n守斗，大臣逆，奸民贼子，欲杀其主。又曰：在阳田宅贱，在\n阴田宅贵。牛。填星逆行牛，女主为奸为贼。土乘牛，为人相\n弃于道。土守牛，诸侯多忠烈，大赦，天下有急。土守牛南，为\n天子忧，守牛北，为美人忧。土守天关，气泄贵人多死。士守\n犯牛，土功事。女。填星入女，有女喜。土犯乘女，人民相恶，\n有女丧。士宿女逆行，变色不安明，女主不亲幸。士守女，多\n妖。女。朝臣幸上。土逆行留守凌女，天子大臣必有变令苛政。\n虚。填星入舍虚中，有赦德令，大人忧，天下大虚。土守虚，天\n下乱，政治急。王出入留虚之中，且有急令，行未当至而至，\n有客兵，不过五日而去，当至不至，其国且用兵。一云兵起。土\n守虚之中，水且为急，进而守之，有客兵，斧铖将用。士入虚\n犯守之，当有急令。星行疾而人，必有客兵，斧钺用，不出其\n年。危。填星入危，天下大乱，若贼臣起。土出人留舍危，其\n国破亡失地，必有流血，其国空虚，有死王，期二年。土守危，\n天子弋猎，天下俭，土入危留守之，其国破亡，有流血，将军\n战死，亡地五百里，必有徙王，期三年。土守坟墓，为人主有\n哭泣之声。室。填星居室，关梁阻塞，出入操持节，贵人多死。\n土犯室，犯阳为阳有急，犯阴为阴有急。土宿室而逆行，女子\n自您。土守室，色黄白，女有分离，赐邑而去者。土守室南，主\n术数金书 中卷\n赐金宝。土守室，为大人恶之，以歉解之。一日太后夫人忧。壁。\n填星逆行壁，女主干治。土守壁，远国献珍宝。土逆行壁，成\n句已，其国必有大兵土功之事，期六月。不下，天子有立王。奎。\n填星入奎，以丧起兵。一"
