   "content": "【乙巳占·乙巳占·OCR第20/56节】（公有领域原典·唐李淳风·星占）\n\n徭役繁多，黜退忠良，进用谗佞，荒于禽色，酣酒嗜音，雕墻\n竣宇，诛戮直谏，残害无辜，听邪言不遵正道，疏绝宗戚，异\n姓擅权，无知小人作威作福，则天降灾样以示其变，望其修德\n以禳之也。不修德以救，则天裂地动，日月薄蚀，五星错度，四\n序愆期，云雾昏冥，风寒惨裂，兵饥疾疫，水旱过差，遂至亡\n国丧身。无所不有，其救之也。君治以道，臣谏以忠，进用贤\n良，退黜谗佞，恤刑缓狱，存孤育寡，薄赋宽徭，矜贍无告，散\n后宫积旷之女，配天下鳏独之男，齐七政于天象，顺四时以布\n令，與人之诵必听，刍荛之言勿弃，行口束帛，以贲丘园，进\n安车以搜岩穴，然后广建贤戚，蕃屏皇家，磐石维城，本枝百\n世，然则此灾可消也，国可保也，身可安也。颂太平者，将比\n肩于市里矣。击壤行歌者，岂一老夫哉！余今略具大纲而已，岂\n能详之者矣。\n辨惑第二十一篇元阙\n史司第二十一\n昔重黎受职，羲和御官，任重上司，位居鼎岳，所以调均\n和气，燮理阴阳，义等盐梅，事同舟楫，故能观天示变，察人\n成化，百工信理，庶绩咸熙，此古之口世。暨三王已降，五霸\n相沿，英贤嗣兴，哲人系踵，君则畏命奉天，臣则竭诚尽虑，故\n能权宜时政，斟酌治纲，验人事之是非，托神道以设教，忠节\n上达，黎庶下安，此中古之贤史也。至若汉魏之后，晋宋相承，\n夷狄乱华，官失其守，君恶直谏，臣矜谄谀，捷径是游，罕遵\n正道。畴人术士俯同卜祝之流，唯辨纤芥之吉凶，验事理之微\n末，推考术数，务在多言屡中，庶征休咎术详。关于政治，玉\n衡倾斜，七政所以不齐；彝伦攸叙，九畴于焉遂隐。此末代之\n流弊也。近在隋代，则尤甚焉。吴人袁充典监斯任，口柔曲佞，\n阿媚时君，诳惑文皇，谄谀二世。每回灾变，妄陈祸福，以凶\n为吉，回是作非，先意承颜，附会神理，劝桀行虐，助纣作淫。\n凡是南人，明相煽惑。于时大业昏暴，崇向吴人，中州高才，言\n不入耳。"
