   "content": "【乙巳占·乙巳占·OCR第26/56节】（公有领域原典·唐李淳风·星占）\n\n有赦，期六十日。火入太微天庭，色白润泽，期一百八十日有\n赦。火入帝座，其色白者为有赦。五星同占。火触犯黄帝座，主\n亡。\n填星占第三十一\n填星，一名地候，中央土德，句陈之精，舍枢纽之使也。其\n性信而圣，其事思而睿，其时四季，其日戊己，其辰辰戌丑未，\n其音宫，其数五，其帝黄帝，其神后土，其虫倮，其味甘，其\n臭香，其卦坤艮。填星为女主之象，坤之气也。言福佑信顺，所\n在之国，大吉之为，聚众土功，所在之分，成国君而兵强。土\n主四季，人君之象，无所不去，故于四时行令，必信而顺，以\n为四行之纲维，犹如地之纪持，以配天成功也。人君象地之载\n不可动，苗稼可收敛蓄积，子以成，百谷以养，则填星黄明光\n润而大。履道不越，以降人君，百禄万福，庆顺之征焉。填星\n所处，君圣臣忠，民信物顺，则填星光明盛大。祥风至，以出\n动万物，人君昌，其国兴。人君若不思虑政道，教令不信，以\n权诈威物，则填星降之不祥，变色微小，其国不昌，大风暴起，\n伤损百物，犹周公居东，成王不信，而大风拔木，邦人斯恐，若\n此之变也。填星主福德，为女主所在之国有福，不可攻伐之，称\n兵动众。填星黄润，女主吉。芒角者，有土功聚众事。色白，女\n主退亡丧。黑色，人君暗国败。赤色，有兵，土与木合，为覆\n军杀将，合战斗，兵内乱。土木合，其邦饥，战不胜，亡地，所\n去之分失地，所入之分得地，益主食。隋二世大业十三年丁丑，\n林钟御律，摄提地候，依于参晋。我大唐时，爰发义旗，肇基\n王业，遂克平宇内，方举乾维，再育苍生，更悬日月。历数钟\n于中运，符瑞感于黄神，圣德溢于百王，奇功迈于上古，此则\n参为唐晋之分。有患死丧，草木枯落，后乃大水败其城郭，雹\n冻伤谷，道路阻塞，暴兵来至，人君失时令，则荧惑错乱逆行。\n乘凌守犯，芒角动摇，句已环绕，无所不为。或下化为人，童\n子妖言并作，惑乱人民，人君忧"
