   "content": "【乙巳占·乙巳占·OCR第48/56节】（公有领域原典·唐李淳风·星占）\n\n为人诚信谦谨。京房云：为上客迁官。丑戌为公正，主报怨仇，主\n兵。京房云：仇谏诤。辰未为奸邪，主欺慢人。京房云：淫佚，疾病\n欺绐。第一本情，甲乙主之。第二合情，丙丁主之。第三刑情，戊\n己主之。第四冲情，庚辛主之。第五钩情。壬癸主之。六合：子\n与丑合，寅与亥合，卯与戌合，辰与酉合，已与申合，午与未\n合。三刑：子刑在卵，卯刑子，丑刑戌，成刑未，未刑丑，寅\n刑已，已刑申，申刑寅，辰午酉亥自刑。对冲：子午，丑未，\n寅申，辰戌，卯西，已亥。已上并冲破也。六钩：子钩西，丑钩\n辰，寅钩亥，卯钩午，已钩申，未钩戌。五合：甲己合，乙\n庚合，两辛合，丁壬合，皮癸合。阳德自处，柔德在天。\n阴阳六情五音立成第七十九\n甲子，阳商，贪狼。本情。甲申，阳羽，贪狼。本情。甲辰，\n已占\n阳徵，奸邪。本情。\n阴徵，宽大。本情。\n阳羽，奸邪。合情。\n阴羽，廉贞。合情。\n阳宫，廉贞。刑情。\n阴宫，宽大。刑情。\n阳商，奸邪。冲情。\n阴商，宽大。冲情。\n阳角，宽大。钩情。\n阴角，奸邪。钩情。\n阳羽，廉贞。本情。\n阴羽，阴贼。本情。\n阳官，宽大。合情。\n阴官，贪狼。合情。\n乙丑，阴商，公正。本情。乙酉，阴羽，宽大。本情。乙已，\n丙寅，阳徵，阴贼。合情。丙戌，阳宫，阴贼。合情。丙午，\n丁卯，阴微，公正。合情。丁亥，阴宫，廉贞。合情。丁未，\n戊辰，阳角，好邪。刑情。戊子，阳徵，阴贼。刑情。戊申，\n己已，阴角，贪狼。刑情。己丑，阴徵，公正。刑情。已酉，\n庚午，阳宫，贪狼。冲情。庚寅，阳角，贪狼。冲情。庚戌，\n辛未，阴宫，公正。冲情。辛卵，阴角，宽大。冲情。辛亥，\n壬申，阳角，宽大。钩情。壬辰，阳羽，公正，钠情。壬子，\n癸西，阴商，贪狼。钩情。癸已，阴羽，贪狼。钧情。癸丑，\n甲成，阳徵，公正。本情。甲午，阳商，廉贞。本情。甲寅，\n乙亥，阴徵，阴贼。本情。"
