   "content": "【乙巳占·乙巳占·OCR第15/56节】（公有领域原典·唐李淳风·星占）\n\n训》日：胃昴毕，魏也。未央《分野》曰：赵星得觜参也。赵本晋地，分晋得\n赵国。汉高帝以邯郸郡为赵国。北有信都、国，汉高帝立也。真定、国，\n汉武帝置之。常山、郡，汉高帝置。本国山为名，日恒山郡。汉文帝讳恒，\n改日常山郡也。中山。汉景帝以郡为国也。又得涿郡之高阳、靳乡，三\n县。涿郡，汉高帝置之也。东有广平、国，汉武帝置之。巨鹿、郡，秦置之。\n清河、郡，汉高帝置之。河间。国，汉文帝分赵国也。又得渤海之东平\n舒、中武邑、文安、菜州、成、章武。六县也，汉高帝置之。河已北也，\n南至浮水、水名，作漳水也。繁阳、内黄、斥丘，三县属魏郡，汉高帝置\n之。西有太原、郡，秦置之。定襄郡、汉高帝置。云中、秦置。五原、秦\n九原郡，汉武帝改名也。朔方、汉武帝置。上党。秦置。上党，本韩之\n别郡也。远韩近赵，后卒降赵，赵皆得之。自赵后九世称侯。四\n世敬侯徙都邯郸。后三世有武灵王，五世为秦所灭。《赵世家》云：\n赵氏之先，帝颛顼之苗裔，伯益之后也。又虞舜妻之姚姓二女，賜\n姓麻氏。历夏殷周，世为诸候。后造父为周穆王御，西巡狩，见西\n王母，乐之忘归。而徐偃王反，穆王日驰千里，还攻徐偃王，大破\n之，乃赐造父以赵。赵城由此，为赵氏。属冀州。《尚书•禹贡》日：\n冀州既载壶口，治梁及岐。《周官》日：河内日冀州。《尔雅》曰：两河间日冀\n州。注云：自东河至西河。未央《分野》曰：赵治邯郸，北至常山、代郡、河间。\n毕、觜、参，晋魏之分野。自毕十二度至井十五度，于辰在申，为实\n沈。言七月之时，万物极盛，阴气沉重，降实万物，故曰实沈。高辛\n氏有二子，伯日阏伯，季日实沈者，不相能，后帝不臧，迁阏伯于商丘，主\n辰，商人是因，故辰为商星。迁实沈干大夏，主参，唐人是因，故参为唐星。\n至周武王感灵梦而生叔虞。成王时，唐有乱，周公灭唐，成王因戏而封叔虞\n于唐，河汾以东方百里"
