   "content": "【乙巳占·乙巳占·OCR第47/56节】（公有领域原典·唐李淳风·星占）\n\n雹霜，或聚在水中。羽日风从阳商来，有斗兵围城不战，边\n有兵，关梁不通，有丧兵不兴。金水母子和，故动角。边兵围城败，\n羽为角除害，象臣为君讨贼。故动必大雨，不出战故也。羽日风从阳角\n来，边兵围城，城败；一云：有兵围城不解。时加已亥为重角，有\n围城若大丧。商日风从阳宫来，戒太子忌怨，人君有疾，兵\n疾，有急兵；宫土，土生金所，是一金两土，母忧子，故日太子也。从\n阴宫来，庶子有急变兵，兵在北方。商日风从阳徵来，国邑\n受令，兵且行，将在外，兵还不战，臣受兵令行；微为号令，商\n为兵。故兵令退也。时加徵为重徵，有大兵行。商日风从阳羽来，\n岁大荒，国凶忧乱，且大雨，兵在东方。商日风从阳商来，有\n白衣聚众之象，立王之征。且大雨，关梁塞，大将出退外敌，外\n敌来邑中，有小急，且有急兵，人君主忧，国四门闭，兵在西\n方。从阴商来，为大殃，籴贵，中有兵，风怒七日七十日，急\n令兵大起。羽入从金生，故为大雨。二金逆行故水，为人主忧大兵斗，主\n国关梁塞也。商日风从阳角来，有急兵令发。\n商日风从阳宫来，人君有忧，兵从申起，国四门闭；从阴\n角来，有大丧，贵人多疾病，有土功。宫为君，角主死，故为大丧\n也。角日风从阳徵来，吏敛民财，若兵出会众，仓粟籴贵，宝物\n出，有蝗虫。角木、火，火为丝绢，故吏敛民财物。角日风从阳羽\n来，有土功，且大雨，边有兵，卿大夫多口疾，先暑风后雨。\n角日风从阳商来，忧有卒兵也，鸣条已上皆应；角日风从阳角\n来，边兵起，人主凶，有死亡，盗贼至，不胜；南方来，有兵，\n远丧至，所不胜；而发时加角为重角，有远丧，有边兵，盗贼\n起，籴贵，野有饥人。角主奖泣，木为金所克也。李淳风按：风角\n书与乐产本多少不同，占验又异。今辄总括，除烦略秽，其有\n时下风来处同者为重其音，此谓时音，与风所发处同，故云重，\n如余所见，与日重有与风重者为异"
