   "content": "【乙巳占·乙巳占·OCR第22/56节】（公有领域原典·唐李淳风·星占）\n\n算及分加之，行分满法，六百七十乃从度一。其日度星度分名，半\n日法也。以星初见去日度数，晨减夕加之，命度以次，则星初见\n所在度分求者，次日各以一日所行度及分。其金火之行而有小\n分者，各以日率为毋，小分满毋法，从去行分满六百七十，去\n从行度日一度。其有益迟益疾者，则别置一日行分，各以疾益\n迟损乃加之，留者因前退即减之。伏不注度，顺行出虚，去其\n分已也，行入斗，先加分。\n岁星初见顺，见顺日行一百七十一分，日益迟一分，一百\n一十四分。日行十九度三百二十三分，而留二十六日乃退。日\n行九十七分，八十四日退十二度一百八十分。又留二十六日乃\n顺行。初日行五十八分，日益度一分疾。一百一十四日，行十\n九度三百二十三分而伏。\n岁星人列宿占第二十五\n角。岁星犯左角，天下之道皆阻塞。犯右角，天下更王，使\n绝灭。守留角中，五谷成熟，留之一百日，兵起。\n木犯守角，王者大赦，忠臣用。木乘左角，法官诛。木乘\n右角，大将军死。木逆行于角，人主出入不时。若有急事，干\n里之行。凡木犯守乘左角七日已上，天下大赦；守右角，贤士\n用，期七十日。\n亢。岁星犯亢，天子坐之，则败于君。木数入亢，其国疾\n疫。木经亢，韩郑有兵。木守亢，小兵。木逆行守亢，为中国\n兵。木犯守亢逆行，失国，其明色，大政不用。\n氐。木犯氐，国无储。木舍守氐，其国岁熟，贱人有疾。木\n乘氐之右星，天下有大水大兵。木乘氐左星，天子有自将兵于\n野。木出入舍氐者，天库之星也。其国有急令，其岁太平，环\n而守之，其国以兵致天下。氐为嬖妾有喜者，若与月合在氐而\n晕，不出四十日有德令。木守氐，王者立后，期十八日。木犯\n逆行守氐，国大饥，人民流亡，亦为人多病。\n房。木入房十日成句已者，为天子恶之，以赦解之。金水\n同占。又日：为皇后夫人丧，谓房东行复还返也。本舍房氐，氐\n色不明；有丧。又日大水。木守"
