   "content": "【乙巳占·乙巳占·OCR第32/56节】（公有领域原典·唐李淳风·星占）\n\n使出，入则使入。干犯灭则为诛罚之象。坠星之所，其下流血\n破军杀将，为咎最深。\n蜀后主建兴十年，诸葛亮帅大众伐魏，屯兵于猬南。有长\n星赤而芒角，自东北西南流投营，三投再还，往大还小。占曰：\n两军相当，有大流星流来走军上及坠军者，皆破败之兆也。九\n月，亮卒于军营而退，群帅交争，多相残诛。\n魏景初二年，司马仲达懿围公孙渊于襄平。八月丙寅夜有\n大流星，长数十丈，色白有芒鬣，从首出东北，流坠襄平城东\n南。占日：围城而有流星来走城上及坠城中者，军破。又目：星\n坠当其下有战伤。又日：凡星所坠，国易姓，九月，渊突围走\n至襄平星坠所，破斩屠城，坑其众。\n景元四年六月，大流星二，并如斗见西方，分流南北，光\n照地，隆隆有声。占目：流星为贵使，星大者使大，是年钟会\n邓艾克蜀。二星二帅之象，二帅相背分流之象应也。钟会既叛，\n三军怒，隆隆有声，兵将怒之验也。凡流星有芒角者及有声为\n怒，色润而迟为喜。疾则事速，缓而事迟。众星皆流，人迁之\n象；星数流者，天下大兵，急使驰驿之象也，皆以色占。色青\n为饥为忧，色赤为旱为兵，色黄为喜为士功，色白为兵为刑罚，\n色黑为病死疾疫。各以其休王占之，各以其日辰所在宿分国属\n而占。\n流星犯日月占第四十一\n流星映日而赤色向日流者，天下不安，帝王易位，人主崩\n亡，百姓逃窜，九州荒芜。流星映日、前锐后方者，王者被大\n臣杀，后宫大乱，天下振动，日月无光，人民大疫，天下半死。\n流星前赤后白、夕见者，大臣欲谋国阴发使。流星昼见、竟天\n阴者，阴有谋臣欲夺国政，诛杀贤良，远期一年，中期二百日，\n下期一百日，必然也。流星夕坠、光耀天者，所坠分野有大兵\n起。一云：有霸王出，流血灾。一云：所坠分野，大疫为灾。\n流星六七一时昼坠地，其分王者死。一云：被迫杀。一云：其\n分大乱，流血为灾。一云：赤旱干里，百泉枯涸，王者受戮。流"
