   "content": "【乙巳占·乙巳占·OCR第6/56节】（公有领域原典·唐李淳风·星占）\n\n世行下道。日不可视，以宿度影晷推之，可知影短则行上道矣。\n列宿当有道之国，日月过则光明，人君吉昌，民人安宁。日或\n黑或赤或黄，有军军破，无军丧侯王。若人君不闻道德，其臣\n乱国背上，则日赤。\n刘向《洪范•五行传》日：汉成帝河平九年正月二日朝，日\n出如血无光，漏上四刻五刻，乃频有光照地赤黄，食后乃复。是\n时成帝无道德，后宫赵氏乱于内，外家王氏擅权，遂至国亡也。\n若臣逆君法，日赤如火，其国遂矣，国亡也。若臣逆君法，日\n赤如火者，其国内乱。\n若阴沉日月无光，昼不见日，夜不见星，皆有云障之而不\n雨，此为君臣俱有阴谋，两敌相当，阴相图议。\n若昼阴，夜月出，君谋臣。\n若夜阴，昼日出，臣谋君。\n若日蒙蒙，并无光，士卒内乱。\n日出一竿无光曜者，其月有三死。若有忧，若人君宰相不\n从四时行令，刑罚不时，大臣奸谋，离贤蔽能，则日月无光并\n见瑕谪。不改其行，其国五谷不成，六畜不生，人民上下纵横，\n盗贼并起。\n日出无光曜者，主病。一日：主有负于臣，百姓有怨心。\n日失色，所临之国不昌。\n日昼昏，行人无影，至暮不止者，上刑下急，民不聊生。不\n出一年，必有大水，下田不收。\n日昼昏，乌乌群鸣，国失政，臣持攻。\n日无云不见光，比三日为大丧，必有灭国。日中鸟见，主\n不明，为政乱其分，国有自衣会，大旱。\n三足乌出在日外，天下大国受殃，戴麻森森，哭声吟吟。\n日光明盛，万物不得视其体，犹人君之尊，权势不可窥逾。\n今日无光，人皆见其体貌，将有伺察神物者焉，人君失其威柄\n之象，特宜修德政以禳之。\n日中有火光气现者，其国君左右大臣欲反。夫祭天不顺，茲\n谓逆祀。\n日中有黑子、黑云，若青若黄赤，乍二乍三，天子崩。按\n《晋中兴书》云：升平三年十月两午，日中有黑子，大如鸡子，\n俄而孝宗崩。晋太和四年十月乙未，日中有黑子如李。至八年\n十一月己酉，天子废为海西公。"
