   "content": "【乙巳占·乙巳占·OCR第2/56节】（公有领域原典·唐李淳风·星占）\n\n下之志，定天下之业，冒天下之道，可大可久，通远逾深，明\n本其宗，致在于兹矣。故日天垂象、见凶吉，圣人则之，天生\n变化，圣人效之。法象莫大乎天地，通变莫大于四时，悬象著\n明莫大乎日月。是知天地符观，日月耀明，圣人备法，致用远\n矣。昔在唐尧，则历象日月，敬授人时，爰及虞舜，在璿现玉\n衡，以齐七政，暨乎三王五霸，克念在兹，先后从顺，则鼎祚\n永隆，悖逆庸违，乃社稷颠覆，是非利害岂不然矣！斯道实天\n地之宏纲，帝王之壮事也。至于天道神教，福善祸淫，谴告多\n方，鉴戒非一。故列三光以垂照，布六气以效祥，候鸟兽以通\n灵，因谣歌而表异。同声相应，鸣鹤闻于九皋；同气相求，飞\n龙吟乎干里，兼复日亏麟斗，月减珠消，晕逐灰移，慧因鱼出。\n门之所召，随类毕臻，应之所授，待感斯发，无情尚尔，况在\n人乎？余幼纂斯文，颇经研习古书遗记近数十家，而遭大业昏\n厶巳占\n凶，多致残缺，泛观归旨，请略言焉。夫神妙无方，义该万品，\n阴阳不测，事同百虑。故景星夜焕，庆云朝集，二明合于北陆，\n五纬聚于东井，此乃表帝皇之盛德，顺天下之嘉瑞也。孛气见\n于夏终，慧星著于秦末，或狗象而东坠，或蛇行而西流，此则\n呈执政之酷暴，逆生民之祸应也。殷帝翦发，沃泽润乎干里；宋\n公请殃，荧惑退移三舍。此则修善之庆，至德可以穰灾也。刘\n裕作逆，以长星为纪瑞；贯丘起乱，以蚩尤为我样。此则覆宋\n之咎，逆招天殃者也。唐尧钦明，镇还水府，殷汤圣政，焦金\n流石，此犹日在北陆而寒，日行南陆而炎暑，月丽篑而多风，\n从毕而多雨，此运数之大期，非关治乱者也，荆轲谋秦，白虹\n贯日；卫生设策，长庚食昴；鲁阳麾指，而曜灵回驾；荀公道\n高，而德星爰聚。此则精诚所感，而上灵悬著也。黄星出，表\n当涂揖让之符；紫气见秦，呈典午南迁之应也。袄象著而殃钟\n齐晋；蛇乘龙而祸连周楚；荧惑守心，始皇以终；流光坠地，"
