   "content": "【乙巳占·乙巳占·OCR第21/56节】（公有领域原典·唐李淳风·星占）\n\n岁星系于麗巽，巽象草木之生动而迟也，又似风雷有时而\n作耳。雷震百里，风为号令。而震动者，人君之象也，故象主\n德焉。\n荧惑系于离。离，火也。凡物之恒动不静者火也，火能照\n明纠察燔烧秽积，故荡除暴。故荧惑，行疾于水，而象体官，察\n狱以罚万物。易日：相见乎离，大人以继明照于四方，故主体\n察焉。\n太白系于乾，为天体行健不息，故金行最急。易曰：悦乎\n兑，战乎乾。故主兵，兵又须有威，故主威。兑为悦，言以悦\n使人，以威临物，乾兑之道也。故太白主兵焉。\n辰星系于坎，坎为水者，昼夜常流，无有休息。故水行亦\n速，与金相似。坎为水为阴，为盗为刑，刑盗于险，司狱之官\n也。故其坎所主于刑焉。\n凡五星之入列宿与中外官，其占大同。但当以理消息其吉\n凶，不可一一具陈也。\n凡月之行也，每去五星十度内，必疾行向之。若道内外则\n屈，屈回就之。过之则迟行，留止不速去。\n又辰星欲见，有时依度合见而入气差。伏者，去之十八度\n内，有星者见，无星则不见。此皆相从就之大例也。并着在历\n术之中，其日蚀交分亦然。其五行代王，四序不一，各于其时\n而为主焉。及其司过见罚，降福呈祥，则大小异其貌，休王殊\n其色。或光润明净。或微细芒角，犯有少异，即可消息占之，不\n必要待其间有斗蚀掩犯也。\n四时之色，春青，夏赤，秋白，冬黑，四季黄。占于列国\n也，则明胜暗，喜胜怒。其优喜之色，则以同前。\n凡五星之内，有三星巳上同宿为合。凡聚合之宿，相生则\n吉事与，相克则凶事起。宿之行性，并于当方为定，兼之宿占，\n而察其事焉。二星明相和大吉，相克大凶。福德先至为吉，刑\n祸先至为凶。刑祸先去为吉，福德先去为凶。一吉一凶，两事\n俱发，但当修德以备之。二星已上聚合皆为改革政令，三星若\n合是谓惊，改立侯王。四星若合是为大荡，其国兵丧并起，君\n子忧，小人流。五星若合是谓易行，改立王者，掩有四"
