   "content": "【乙巳占·乙巳占·OCR第3/56节】（公有领域原典·唐李淳风·星占）\n\n成。凡至大莫若天，至厚莫若地也。至质者，日地而已。至多\n莫若水，水精为汉，周于天而舞列焉。思次质也。地有山岳，以\n宣其气，精种为星。星也者，体生于地，精成于天，列居错時，\n各有攸属。紫宫为皇极之居，太微为五帝之庭。明堂之房，大\n角有席，天市有座。苍龙连蜷于左，白虎猛踞于右，朱雀奋翼\n于前，灵龟圈首于后，黄帝轩辕于中。六扰既畜，而狼蚖鱼鳖，\n罔有不具。在野象物，在朝象官，在人象事，于是备矣。悬象\n著明，莫大乎日月，其径当天周七百三十六分之一，地广二百\n四十二分之一。日者阳精之宗，积而成鸟，象鸟而有三趾。阳\n之精，其数奇。月者阴精之宗，积而成兽，象兔而乃缺唇。阴\n之精，其数偶。其后有穷羿者，羿请不死之药于西王母。姮娥\n窃之以奔月，将往求筮于有黄，有黄占之日吉：翩翩归妹，独\n将西行，逢天晦芒，无恐无惊，后且大昌。姮娥遂托身于月，是\n为蟾蜍。夫日譬犹火，月譬犹水。火则外光，水则含景。故月\n光生于日之所照，魄生于日之所蔽。当日则光盈，就日则光尽。\n巳占\n众星被曜，因水转光，当日之冲，光常不合者，蔽于地也。是\n谓暗虚。在星星微，遇月则食，日之薄地，暗其明也。由暗视\n明，明无所屈，是以望之若大，方于中天，天地同明；由明瞻\n暗，暗还自夺，故望之若小。火当夜而扬，光在昼则不明也。月\n之于夜，与日同而差微，星则不然，强弱之差也。众星列布，其\n以神著，有五列焉，是为三十五名。一居中央，谓之北斗。动\n变挺占，实司王命，四布于方，为二十八宿。日月运行，历示\n吉凶，五纬蹥次，用告祸福，则天心于是见矣。中外之官，常\n明者百有二十四，可名者三百二十，为星二千五百，而海人之\n占未存焉。微星之数，盖万一千五百二十。庶物蠢蠢，咸得系\n命。不然，何以总而理诸？夫三光同形，而有似珠玉，神守精\n存，丽其职而宣其明。及其衰也，神歇精斁，于是乎有陨"
