   "content": "【乙巳占·乙巳占·OCR第45/56节】（公有领域原典·唐李淳风·星占）\n\n干里；半日半夜三时已上，事及五百里；三时已下，事及百里。\n此以时多少，推灾及远近。凡大树拔根，事及三千里外；折大枝，事\n及二千里。此以势力占灾远近。凡风近起城郭中者，有急事；卒起\n宫宅中者，为左右有变事。风自百里已上来者，皆谓其风时缓时\n急，条长垂索索然者是也。若蓬勃乍起乍止，卒缓卒急，势无\n常准者，并二百里以内，非远来，为灾乃重。若当时有云雨雷\n电者不占，其应四时灾日兼雷雨而发者，并依别占。周成王偃\n禾之风是也。淳风日：天下地气，有偏饶风处，或近山川，或\n近大水，皆以异常为占，而山川记复有近风穴处。然风发出之\n时，皆有所应。然风或发一时间，远乃至十日已上者，灾重。而\n京房《风角》又有推五音风所发远近，各以其五音之数，期风\n来处远近。凡风发，一日为其县，二日他县，三日其郡，四日他\n郡，五日其州，六日他州。各以日数，知灾所及。一云：凡风\n一日一夜为邑，二日三日为州，四日五日为国，六七日为天下。\n凡五音，有纳音中金木水火土定五音者，有十二辰配五音，有\n听声配五音。宫风，近十里，中百里，远千里。宫之数也。羽风，\n近六里，中六十里，远六百里。徵风，近七里，中七十里，远七\n百里。角风，近八里，中八十里，远八百里。商风，近九里，中\n九十里，远九百里。淳风曰：案京房《角风》所载，五音风发远\n近，皆以五行成数推之。其云远近及中者，皆以日时多少及势\n力强弱以事准之。推其远近，皆变通其数，触类长之，而风所\n从来二十四处，皆须明知发止。审别支干及以八卦所在发时早\n晚，来从何处，息在何时，回在何日何辰，皆须审明知之。凡候\n风之体，须明知入卦，审识支干，或上或下，或高或卑，必晓\n此义，然后可验，必无乖越。若失在毫末，差深干里。今设八\n方之法：八干，甲乙两丁庚辛壬癸；四卦，乾坤艮巽。八干、四\n卦、十二辰总有二十四分，皆立方，迭"
