   "content": "【乙巳占·乙巳占·OCR第8/56节】（公有领域原典·唐李淳风·星占）\n\n而寒乃蚀者，四方正伯专诛，您行杀逆。日蚀而大寒，又在\n于平旦，中国大饥饿，贼盗起，夷狄动，诸侯乱。日蚀星坠\n而复上，君将被杀，下将穷竭，赋敛重数之应。日月俱蚀，国\n亡。日者人主之象，故王者道德不施，则日为之变。薄蚀无\n光，日以春蚀，大凶，有大丧，女主亡。夏蚀无光，诸候死。秋\n蚀，兵战，主人死。冬蚀，有丧，多病而疫。 凡四时以王日\n蚀者，主死。 以相日蚀者，国相死。以囚死日蚀者，臣杀\n君。 休废日蚀者，多病疫。日以正月蚀，人多病；二月蚀\n多丧；三月蚀大水；四月、五月蚀，大旱，民大饥；六月蚀，六\n畜死；七月蚀者岁恶，秦国恶之；八月蚀者兵起；九月蚀者女\n工费；十月蚀者六畜费；十一月、十二月蚀者，籴贵，牛死于\n燕国。其日之甲乙，一如略例中，蚀列宿占。日在角蚀，将\n吏耕田。臣有忧为司农之官者。国四门闭，其国凶。月同。日\n在亢蚀，朝廷之臣有谋叛。 日在氐蚀，天子病崩，卿相谗谀，\n君杀无辜，王后恶之。 日在房而蚀，王者忧疾病有乱。又大\n臣专权。月同。日在心而蚀，君臣不相信。政令失仪度，准绳\n变其宜。日在尾蚀，将有疫，后官中小凶。日在箕蚀，将有\n疾风飞砂，发屋折木，戒之于出入。日在斗蚀，将相忧，国\n饥兵起。月同。日在井蚀，其国反叛兵起，戒在后夫人祠祷之\n咎。 只在女蚀，戒在巫祝后妃祷祠。日在虚蚀，其邦有崩\n亡，天下改服。月同。日在危蚀，有大丧，君臣改服。日在\n室蚀，人君出入无禁，好女色，外戚专权。日在壁蚀，则阳\n消阴坏，男女多伤败其人道，王者失孝敬，下从师友，亏文章，\n损德教，学礼废矣。日在奎蚀，鲁国凶，邦不安，慎在人主、\n边境厩库。日在娄蚀，戒在聚敛之臣。日在胃蚀，委输国\n有乏食之忧。日在昴蚀，大臣厄在狱，王者有疾，戒在主狱\n有犯误天子者。日在毕蚀，将有边将亡，人主有弋猎之咎。日\n在觜蚀，大将谋议，戒在将兵之臣。 "
