   "content": "【乙巳占·乙巳占·OCR第43/56节】（公有领域原典·唐李淳风·星占）\n\n帛广，前锐后大，将军行气也。干岁龟，上有白云。韩云如布。\n周云如车轮。秦云如行人。卫云如犬。魏云如鼠。齐云如绛衣。\n越云如龙。蜀云如困车。气乍高乍下，往往而聚骑，气卑而布。\n卒气，转前高后卑者，不止而返。校骑之气，正苍黑，长数百\n丈；游兵之气，如彗扫。喜气，上黄下白；怒气，上黄下赤；忧\n气，上下黑；土功气黄，白徒气白。凡候云之法，气初出时，若\n•\n云非云，若雾非雾，仿佛若可见，初出森森然，在桑榆上，高\n五六尺者，是千五百里外。平视则千里，举目望则五百里，仰\n瞻中天百里内，平望桑榆间二千里，登高山而望四下属地者三\n千里。凡欲知吾军，常以甲己日及庚子戊午未亥日，八月十八\n日，去军十里，登高望之可见。依别记占之，百人已上皆有气。\n凡占灾异，先推九宫分野，六壬日月，不应阴雾风雨者，乃可\n占。对敌有云来甚卑，掩沟盖道，是大贼必至，食不及饱，急\n起严备之。敌在东，日出候；在南，日中候；在西，日入候；在\n北，夜半候。凡气在王相色，吉；在囚死色，凶。凡军上气，高\n胜下，厚胜薄，实胜虚，长胜短，泽胜枯。凡气，欲似甑上气\n勃勃上升，积为雾，雾为阴，阴为结为虹蜺晕珥之属。凡气不\n积不结，散漫一方，不能灾，必须和杂杀气，森森然疾，乃可\n谕占。军上气安则军安，气不安则军不安，气南则军南，气北\n则军北，气东则军东，气西则军西，气散则军破散。候气常以\n平旦、下脯、日出没时处气见以知。夫占之期内，有大风雨久\n阴，则灾不成。故风以散之，阴以疏之，云以藏之，雨以解之。\n云气人列宿占第六十五\n角宿。有云状如刀剑。口口口角间有忧，阴谋起，天子下\n殿。有云苍色入左角，兵散；出右角，战有忧。\n亢宿。有云入亢，人民疾疫。有气入亢出氐，君主疾。\n氐宿。有苍白云入氐，天下大疫疹流行。有黑云入氐水灾。\n房宿。有赤云状人入房，后有娠。不然，奸事起。有气"
