   "content": "【乙巳占·乙巳占·OCR第24/56节】（公有领域原典·唐李淳风·星占）\n\n夏行秋令，则太白之气干之，色白而昧，若雨数至，水涝，五\n谷不滋，四鄙入堡，草林零落，果实早成，民多疾疫，孕女多\n成，有大丧。以夏行春令，则岁星之气干之，色青而变，人君\n有忧，蝗虫为灾，暴气未格，秀草不实，五谷晚熟，百媵时起，\n其国乃饥，谷实鲜落，民乃迁移。以夏行冬令，则辰星之气干\n之，色黑而怒，年兵起。壁。荧惑入壁中三月，卫国君死，入\n五月，相死，不死走出。二十八宿同有此占。火守壁，为天下兵起。\n一日狄起。木同。火入壁留守之，有土功。奎。荧惑入奎中，人\n多疾。火入奎中三月，鲁主死；入旬，相死，不死相走。二十\n八宿同占。火人奎环绕之三十日，相死；三月不行，其国王死，\n不死走出，期三年。火守奎移动进退，为赦。又曰：天下大水，\n民多死。火守奎二十日已上，大臣有谋国，有兵。若有死王，加\n兵于鲁国之地，期一年。娄。荧惑入娄而守之，天下有聚众，兵\n大起，车骑用，必有死君走相，天下不熟，民饥非一国。若山\n林有大盗，道路阻塞，期一年，远二年。火入娄，成句已，困\n有焚烧仓库府库之事。若逆行至奎，大兵起，臣谋将军为乱，期\n不出年。火守娄卒，人病，大小金银贵。火入守娄，其国坐之。\n一目：守三十日，其国君有忧。胃。荧惑入胄二十日，天下有\n兵敌，仓廪粟出。火守胃，其年旱饥，民多疫，王者行仁则吉，\n此火克金，以礼教义天下，无咎。火入胃而守之，三十日不下，\n赵地大急，人民半死，大兵起，客军败，主人胜，期不出一年。\n火入若守胃东出，民扰。昴。荧惑犯昴，若入之，胡人聚中国，\n匈奴大出，四夷兵起，国有忧。火入昴，天下不安，兵起，有\n兵，兵亦罢。四月、五月大赦。近期十五日，远期三十目赦。又\n日：不可为客。一目：贵人多戮死者。火守昴，无罪者诛。火\n守昴，胡人不宁。火入昴，已去复还守之，有臣为天子破军匈\n奴者，期三年。火犯昴，胡民疾病。一目"
