   "content": "【乙巳占·乙巳占·OCR第41/56节】（公有领域原典·唐李淳风·星占）\n\n气如飞鸟，城可攻，急击之，则破走。城上有赤气如破车，城\n可攻。城上无云气，士卒必败散。城营中有赤气，状如狸皮斑\n及正赤者，并破亡将败。城上气如死灰色及上下出者，城可攻。\n一云：攻城围邑，其气如灰气出而覆其一军上者，多病，城可\n屠；气出复入者，人欲逃背，攻城围邑；城上气聚如楼见外者，\n攻之可得。望城中气起而正上赤，可屠。城营上有云如众人头\n赤色，下多流血死丧。攻城围邑，其上气色如灰，一云灰，城\n可屠；气出南北，城可克；其气出复入城中，人欲逃背；其气\n出而东，城可攻；其气出而西，城可降；其气出而复其军上者，\n士多病；其气出而高无所止，用日久长。有气从城外者，兵欲\n盗攻。攻城黑云临城者，积土固险之象。黑水之气，城池之称。\n我据城，敌不能为我攻，故不可攻。又曰：审应而无攻，知难\n而自止，因可用智不败。有白气如蛇，来止敌城上者，急攻之，\n小缓则失；从其城来指我营者，宜急固守。凡攻城，有白气绕\n城而入城者，随所入，急攻之，小缓则失；从其城来指我营者，\n宜急固守。攻城若不雨濛雾，日死风至，兵胜；日色无光为日\n死，云气如雄雉临阵，其下必有降者。濛云围城而入城者，外\n胜得入。有云如立人五校，或如三牛，边城围。城上有蛟头白，\n内降，城可攻；若有屈虹从外入城中，三日内，城可屠。日重\n晕而有白虹贯日，围城客胜。\n伏兵气象占第五十九\n军上有黑气浑浑圆长，赤气在其中，其下必有伏兵，不可\n击。军当欲战，或长相守者。望彼军上白气粉沸起如楼状，其\n下必有藏兵万人，不可轻击。军行近山林坑谷之间，当善防之，\n既是伏兵之地，而上有气者不疑。云纷纷绵绵相绞及似蒿草数\n尺，车骑为伏兵。云如布席之状及似蒿草尺许此，以步卒为伏\n兵。伏兵之气，如幢节状在乌云中，或如赤杵在乌云中，或如\n乌人在赤云中。黑气出营南，贼逃吾复有伏兵，谨候察之，有\n覆之无遗"
