   "content": "【乙巳占·乙巳占·OCR第4/56节】（公有领域原典·唐李淳风·星占）\n\n先側立二大环卷，南北侧之，以平准卷交合加之，令侧者为南\n北，径准为主。\n一目游环。游环上安红钏，游环着双轴，以内大环轴孔中，\n令得运转。轴中一圆长筒管。其筒孔周径，准仪大小而斟酌之。\n若长八尺，即须孔径一寸，他皆准此。其侧环安红钏之处，在\n北者调之北极，出平准北面上三十六度；在南者谓之南极，入\n平准南面下三十六度。从其南端北向斜上望之，即见北极星。又\n以一天环加于侧环外，斜络之，令东西合于卯西平面之准，南\n北上下去二极，各九十一度强，以为赤道。然后转其中游环，令\n得左右、东西、上下以当所望处，转轴中筒孔，使得南北以测\n去极远近及赤道内外之度数，然则筒孔瞻察，无所不至矣。若\n欲安星辰者，更著从胁上屈铜铁，穿珠为星，以放上象，随所\n在次第而安置之，转令应天皆得，此浑天游仪之法也。按浑仪，\n必先以水准地使平，夜占极，昼测日景，定其经纬，然后措之\n矣。余近造乙巳元历术，实为绝妙之极，日夜法度诸法，皆同\n一母，以通众术。今列之以推天度，日月五星行度皆用焉。\n日度法一千三百四十，以此数为一度之长分数也。周天有\n三百六十五度、一千三百四十分度之三百四十一。南极去北极，\n巡规一百八十二度、一千三百四十分之八百四十半。赤道去二\n极，巡规各九十一度、一千三百四十分之四百二十分、小分四\n分之一，即春秋分之所在度。黄、赤二道交处，去北极之远近\n也。黄道出入赤道二十四度，冬至日在赤道外二十四度，去极\n一百一十五度、一千三百四十分度之四百二十分、小分四分之\n一。夏至日在赤道内二十四度，去北极六十七度、一千三百四\n十分度之四百二十分、小分四分之 。此其常数也。\n淳风今又按：张胄《玄象历》及今传《仁均历》，春分、秋\n分，日皆在卯半以前，其没亦在酉半以后，各四分刻之一。春、\n秋二分之日，昼漏五十刻半，夜漏四十九半，然则赤道、黄道\n交处"
