   "content": "【麻衣道者正易心法·麻衣道者正易心法·OCR第5/7节】（公有领域原典·宋陈抟·易心法）\n\n变而为一也。一者，形变之始也。清轻者上为天，重浊者\n下为地，冲和气者中为人。谓之《易》者，知阴阳之根本\n有在于是也。此说本于《冲虚真经》，是为定论。学者盲然\n不悟，乃作变《易》之《易》，是即字言之，非宗旨之学也。\n唯扬雄为书，拟之日《太玄》，颇得之。道家亦以日月为古\n之易字，盖其本阴阳而言也。\n《易》道弥满，九流可入。当知活法，要须自悟。四十一章\n《易》之为书，本于阴阳。万物负阴而抱阳，何适而\n非阴阳也？是以在人惟其所入耳。文王、周公以庶类入，宣\n父以八物入，斯其上也。其后或以律度入，或以历数入，或\n以仙道入。以此知《易》道无往而不可也。苟惟束于辞训，\n则是犯法也，良由未得悟耳。果得悟焉，则辞外见意，而\n纵横妙用，唯吾所欲，是为活法也。\n故曰：“学《易》者当于羲皇心地中驰骋，无于周、孔\n言语下拘挛。\n世俗学解，浸溃旧闻。失其本始，《易》道浅狭。四十二章\n羲皇氏正《易》，《春秋》比也。周、孔明《易》，作传\n比也。左氏本为《春秋》作传，而世乃玩其文辞，致左氏\n孤行，而《春秋》之微旨泯矣。《易》之有辞，本为義皇发\n扬。学者不知借辞以明其画象，遂溺其辞，加以古今训注\n而袭谬承误，使羲皇初意不行于世，而《易》道于此浅狭\n矣。呜乎！\n麻衣道者正易心法\n麻衣道者正易心法序\n麻衣道者《羲皇氏正易心法》，顷得之庐山一异人。或云许\n坚。或有疑而问者，余应之云：“何疑之有？顾其议论可也。”昔\n黄帝《素问》，孔子《易大传》，世尚有疑之，尝日：世固有能\n作《素问》者乎？固有能作《易大传》者乎？虽非本真，亦黄\n帝、孔子之徒也。余于《正易心法》，亦曰世固能有作之者乎？\n虽非麻衣，是乃麻衣之徒也。胡不观其文辞议论乎？一滴真金，\n源流天造，前无古人，后无来者。翩然于羲皇心地驰骋，实物\n外真仙之书也。读来十年方悟，浸渍"
