   "content": "【麻衣道者正易心法·麻衣道者正易心法·OCR第1/7节】（公有领域原典·宋陈抟·易心法）\n\n跋二\n麦麴鞠，廋词之祖也。伏文见志，比拟耳。柏者迫，窦者豆，\n漫语谐声，何关机事？祸福成败，率凭而得之，袭袭相承，后世\n遂有专家之学。晰句辨画，可以配宓羲；立体损文，可以当莼莛。\n记目：“人心之灵为之也，天与人实相半矣。”栎下先生，无书不\n读，间亦好析宇寮言。宏追随二十年，时当宾朋杂坐，酒热灯红，\n偶事绪脚蹰，群疑如漆，随拈一字，击射分涂，理解神披，俱成意\n义。事后，惟先生中者十，否亦十得五。坐客门生，或十得三四，\n或得一，或尽不得，莫不抚掌欢笑，窃比神明。居常举一二事以耀\n同人，不谓《字触》之书，更俨然成帙也。因叹天下之事何常，人生\n之理何尽，鬣者安知其不为牛，角者安知其不为马？竖儒小生，泥\n一偶之见，胶方刻水，欲以尽天下之理，尽天下之事，岂复能有当\n哉？引而申之，先生之言小也，请以喻大。\n弟子黎士宏跋于回光禅院\n跋三\n右《宇触》六卷，国朝周亮工撰。按亮工字元亮，祥符人。先\n世居金溪之栎下，因自号栎园。又称栎下先生。事迹具黄虞稯所\n撰《行状》及王障（今世说》各条。著有《赖古堂集》、《因树屋书\n影》、《闽小纪》、《尺牍新抄》等书。吴梅村称其有墨癖，尝奋墨万\n种，岁除以酒浇之，作《祭墨诗》，亦韵事也。是书虽偶然游戏之\n笔，编类成书，却极详赡。偶阅赵云松《陔余丛考》“谜”一条，“测\n字”一条，所授群书，亦间遗一二，而固不足以傲栎园也。至所称\n少时见一拆字者，一人来问父病，随手拈得“一”字，日：“一字，生\n字之尽，死字之初也。汝父殆不起矣。问汝父生年云何？”其子目：\n“丁丑生，属牛。”日：“然则汝父不死。牛加一画，则生字矣。”云\n云。则云松所亲见者耳。又张岱《陶庵梦忆》，记谢文正听事名\n“保锡堂”。后易之他姓，主人至，亟去其扁。人问之，曰：“分明写\n‘呆人易金堂’。”朱石门为文选，署中额“"
