   "content": "【麻衣道者正易心法·麻衣道者正易心法·OCR第6/7节】（公有领域原典·宋陈抟·易心法）\n\n者，四时向背之气也。假令六甲六乙生日，春生则无官，夏生则有财，秋\n生则向禄，冬生则生旺。秋生得甲己酉丑或壬成庚辰，则有官印重矣。若\n生时刦居寅午戌已上，更有戊己两了在时中则官减半。盲之如本位配两丁\n南方火位，亦夺甲之印也。五行当权者用之为福，不当权者用之无庆，假\n令金用火为官印，九夏生则向官，七月生则气退，即官不迁进也。当用之\n神旺相，则有庆，死囚体败则退也。又如水命人以士为官印，都得十月正\n月二月生，虽有土而不中用也，以五行退则不当权而休息。此论五行气退\n珞禄子三命消息赋注\n罢权之道，如蛇鳝之在灰尘，则何可长久也。\n其为有也，是从无而立有；其为无也，天垂象以为文。此五\n行论于绝地而建贵也，五行绝处有禄马，假令丁亥两子庚寅甲申乙酉戊寅\n壬午癸已己卵已亥，皆从无天元，受绝休囚之地，却成贵强之位。鬼谷曰：\n干虽绝而建日成。鉴日：受气推寻，胎月须深。亦当论生日天元破绝而贵\n也。赋言五行穷绝处无也，绝中建禄则有也。凡此者皆合大道，贵而清也。\n易日：脏悬象著明莫大乎日月，日月者天之文也，阴阳之柄也。日往则月\n来，暑往则寒来，皆一生造化之文也。\n其为常也，立仁立义。其为事也，或见或闻。五行者在天为\n五星，在地为五岳，在人为五脏，推而行之则为五常，常有可久之道，则\n秉乎仁义者。易日：立天之道，日阴与阳，立地之道，日柔与刚，立人之\n道，日仁与义，人之道，非仁与义则不能立也。命遇金者必要木，有木须\n要金，是谓有刚济柔，仁而尚勇，遇此格者多贵。賦曰：金木定其刚柔是\n也，其为也者，令术者将人生年月日时中支，匹配吉凶作为也，或见者年\n月日时上天元也，或闻者支内人元也，甲在寅之类，又辰乃水土之库，成\n火库，丑金库，未木库。辰中有乙是春木之余气，未中有了是夏火之余气，\n戌内有辛是秋金之余气，丑中有癸是冬水之余气"
