   "content": "【麻衣道者正易心法·麻衣道者正易心法·OCR第7/7节】（公有领域原典·宋陈抟·易心法）\n\n有灾，如当生岁月日时，元无七煞则灾轻，故赋中引宣父畏以元辰者，即\n非前位元辰也，是当生年月日时位元，有七煞害生月生时者，乃名元有元\n辰也，即为灾重矣。虚中云：当生元有则凶重，无则凶轻。所以宣父畏以\n元辰者，是宣父命中元有煞害之后也。又戊见甲己见乙为七煞，戊己人在\n十月生正月生，虽生时居已午，或更有庚辛亦天寿，为土死不能生弱金，\n金囚不能胜旺木。赋云：建禄而天寿。余仿此。昔者峨眉先生精通三命，\n每言贵贱少有全者。鬼谷先生以九命之术，纳以星宫，为此赋前贤自谦而\n言之，与物难穷理则同也。\n臣出自兰野，幼慕真风。入肆无悬壶之妙，游衢无化杖之\n神。息一气以凝神，消五行而通道。臣者，太子自称君父之前也。生\n于内庭有芝兰之野之称。真风者，自幼乐于五行之真理者也。昔有悬壶先\n生，货卜于市，国君闻而召之，先生拒命而不往。君今执之，先生预知，\n以杖化龙乘而去。息一气者，天元也。五行者，金木水火土也。凝聚也，\n消散也。通道者，符合也。阴阳不偏，上下符合则能知造化，而贵贱吉凶\n寿天定矣。犹然自谦，无化杖乘龙之为也。\n乾坤立其牝牡，金木定其刚柔。昼夜互为君臣，青赤时为\n父子。乾阳物也。坤，阴物也。凡看命，见五行阴阳匹配，上下相合不偏\n者，为贵命也。若偏阳偏阴者，则五行有疾矣。金木定其刚柔者，且如木\n用金为官印，其金秋生或带壬癸水而克木即刚也，谓金旺时水木无火则金\n刚矣。若金生于秋，夏木带天元人元有火，则木刚金柔也。昼阳而夜阴，\n阳为君，阴为臣，日月相催，昼夜相代，则互为君臣也。青赤时为父子者，\n丁壬合生甲已壬生甲，壬乃甲之母，丁乃甲之父，丁生已，已以壬为父，\n丁乃已之母。甲己再合，己生辛，甲生丙，丙辛丙合，丙生戊，辛生癸，\n戊癸再合，戊生庚，癸生乙，乙庚再合，乙生丁，庚生壬，丁壬再合，复\n生甲己，周而复始，人"
