   "content": "【麻衣道者正易心法·麻衣道者正易心法·OCR第4/7节】（公有领域原典·宋陈抟·易心法）\n\n丰、明夷、师，八变而复坎，则水之气尽。离、旅、鼎、未\n济、蒙、涣、讼、同人，八变而复离，则火之气尽。巽、小\n畜、家人、益、无妄、噬嗑、颐、蛊，八变而复巽，则风\n之气尽。兑、困、萃、咸、蹇、谦、小过、归妹，八变而\n复兑，则泽之气尽。凡此八卦，各八变，八八六十四数，则\n天、地、雷、风、水、火、山、泽之气无余蕴矣。是为一\n义。\n数成于三，重之则六。其退亦六，是为乾坤。三十二章\n夫气之数，起于一，偶于二，成于三，无以加矣。重\n之则为六也。然三，少阳也。六，太阳也。三，春也。六，\n夏也。此乾之数也，是为进数。其退亦六。三，少阴也。六，\n太阴也。三，秋也。六，冬也。此坤之数也，是为退数。三\n画为经卦，六画为重卦者，凡以此而已。\n凡物之数，有进有退。进以此数，退以此数。三十三章\n大抵物理，其盛衰之数相半。方其盛也，既以此数。及\n其衰也，亦以此数。若一岁十二月，春夏进数，秋冬为\n退数。昼夜十二时，自子为进数，自午为退数。人寿百岁，\n麻衣道者正易心法\n前五十为进数，后五十为退数。以至甲为进数，乙为退数。\n子为进数，丑为退数。细推物理，无不然。世儒论教，但\n衍为一律，殊不明阴阳进退之理，惟真人独得其说。\n凡具于形，便具五数。五数既具，十数乃成。三十四章\n凡丽于气者，必圆。圆者，径一而围三。天所以有三\n时者，以其气也。凡丽于形者，必方。方者，径一而围四。\n地所以有四方者，以其形也。天数三，重之则六。地数五，\n重之则十。何谓十？盖有四方，则有中央，为五。有中央\n四方，则有四维，复之中央，是为十也。非特地为然，凡\n丽于形，便具十数，皆若此也。\n大衍七七，其一不用。凡得一数，理自不动。三十五章\n大衍之数五十。其用四十有九，卦一而不用。不用之\n义，学者徒知一为太极不动之数，而不知义实落处也。何\n则？一者，数之宗本"
