   "summary": "",
   "content": "【麻衣道者正易心法·麻衣道者正易心法·OCR第2/7节】（公有领域原典·宋陈抟·易心法）\n\n谓包括万象，而易道所以大也。\n麻衣道者正易心法\n乾坤错杂，乃生六子。六子则是，乾坤破体。九章\n三乾三画奇，纯阳也。一阴杂于下，是为杆巽。杂于\n中，是为三离。杂於上，是为三兑。巽、离、兑，皆破乾\n之纯体也。坤三画偶，纯阴也。一阳杂於下，是为三震。杂\n於中，是为三坎。杂于上，是为三艮。震、坎、艮，皆破\n坤之纯体也。若更以人身求之，理自昭然。\n粤乾舆坤，即是阴阳。圆融和粹，平气之名。十章\n凡阴阳之气，纯而不驳，是为乾坤。《老子》日：“天\n得一以清，地得一以宁。”正谓此也。因知能尽乾之道，是\n为圣人；能尽坤之道，是为贤人。\n至於六子，即是阴阳。偏酸反侧，不平之名。十一章\n乾健坤顺，阴阳之纯气也。一失健顺，则不平之气作，\n而六子生，观画象可知。《庄子》日：“阴阳错行，天地大\n骇。有雷有霆，水中有火，乃焚乃块。”正谓此耳。由是六\n子非圣贤比，特众人兴万物而已。然由破体炼之，纯体乃\n成。\n健顺动入，陷丽止说。非特乾坤，六子训释。十二章\n非特训释，盖谓不可专于八字上取也，当求之于画象。\n健谓三画纯奇是，顺谓三画纯偶是，动谓一阳在二阴下是，\n入谓一阴在二阳下是，陷谓一阳在二阴中是，丽谓一阴在\n二阳中，止则一阳在二阴上是，说则一阴在二阳上是。凡\n有所训，多见於画象。如阖户谓之坤，则姤之初爻是。关\n户谓之乾，则复之初爻是。\n坎兑二水，明须识破。坎润兑说，理自不同。十三章\n坎乾水也，气也，若井是也。兑，坤水也，形也，今\n雨是也。一阳中陷于二阴为坎，坎以气潜行於万物之中，为\n受命之根本，故日润万物者莫润乎水。盖润，液也，气之\n术数全集 中卷\n液也。一阴上彻于二阳为兑，兑以形普施于万物之上，为\n发生之利洋，故曰说万物者莫说乎泽。盖说，散也，形之\n散也。坎、兑二水，其理昭昭如此。学者依文解义，不知\n落处，其能得实"
