   "content": "【麻衣道者正易心法·麻衣道者正易心法·OCR第3/7节】（公有领域原典·宋陈抟·易心法）\n\n正谓上下二体也，伏谓二体从变也，互谓一卦有二互\n体也，参谓二互体参合也。与本卦凡八，是谓一卦具八卦\n也。然一卦何以具八卦？盖一卦自有八变，如乾一变姤，二\n变遁，三变否，四变观，五变剥，六变晋，七变大有，八\n变复乾是也。因其所然，以见天地万物理无不通也。《庄\n子》论久竹生青宁，青宁生程，程生马，马生人，人死反\n入于机，万物皆出于机人于机。其一节论变化之理，无所\n不通如此。\n六十四卦，唯乾与坤。本之自然，是名真体。二十章\n麻衣道者正易心法\n太初者，气之始，是为乾。太始者，形之始，是为坤。\n皆本之自然，无所假合也。故其卦画纯一不驳，倒正不变，\n是名真体。\n六子重卦，乾坤杂气。悉是假合，无有定实。二十一章\n六子假乾坤以为体，重卦合八卦以为体。若分而散之，\n则六子重卦皆无有定体也。若今天地清明，阴阳不杂，则\n六子何在？六子不交，则品物何在？以是知人间万事，悉\n是假合。阴阳一气，但有虚幻，无有定实也。\n卦义未审，须求变复。不唯辞合，义实通明。二十二章\n变为一爻之变，复为一体之复。即复变之辞而观之，自\n然之义，无不与本卦吻合，以见阴阳之气。如蒙上九目\n“击蒙。”变为师，上六则云“小人勿用。”屯初九日“以贵\n下贱，大得民也。”变为比，初六则云“有孚比之，无咎。”\n此一爻之辞合也。如大有上体复需，有饮食之燕；下体复\n晋，有昭明之德。升上体复姤，姤一阴升；下体复复，复\n一阳升。此一体之义合也。苟卦义未审，能以此求之，自\n然明矣。\n古今传易，舛讹为多。履畜八体，最为害义。二十三章\n按卦序，当先履而后小畜。今小畜在先，则二卦画象\n反对，文义缪乱，而不可考。又以八卦本对八体，独阙其\n鼻。乃以巽言股，股即系是也。若股可言，则又遗其肱，且\n与羲皇八卦不相应也。兹盖传者舛误耳，能不害义乎？试\n辩之。一柔自姤变同人，"
