   "content": "【字触·字触·OCR第8/19节】（公有领域原典·清周亮工·测字）\n\n扯长而已。”\n瓜\n子\n以瓜子问父病，目：“死期近矣。合瓜子为孤字，固知必不生\n矣。”\n汗\n巾\n一人以汗巾问府取有无，目：“不但府取，兼入泮，定有衣巾。\n盖布为有字形，汗为泮字形也。巾者衣巾，布色新泽，必有更新之\n意。”\n有一权贵无子，知龙名，以门生袁姓者补南工部员外，\n寄一白围棋子，托问后嗣。袁至，微服付棋子占之。龙目：\n“公姓袁否？”日：“然。我何如人？”龙以手周围摸之曰：“员\n外。”目：“我所占何事？”日：“此白物也，应自北来，必自北京\n当局之贵人。其第一著所卜者，惟其子乎？”曰：“有无何如？”\n日：“此物非木非石，经水火锻炼而成，全无生气，安得有子？\n以理而推，亦当谢局，须急下官著可也。”已而权贵卒于任，\n竟无子。术之奇确如此。\n麻\n雀\n徽守见龙之门如市，恐其惑众，意欲处之。一日召至，问：“我\n手中何物？如合，则释尔。不合，毙杖下矣。”龙求指一物示之，方\n好卜决。时堂下有少妇诉冤，守即指此妇为数。龙日：“一麻雀\n耳。”守惊日：“生乎死乎？”龙曰：“生死在老爷掌握中。”守曰：“此\n歡可与语数也。”盖日生则毙之，日死则出之，守已知其喻意矣。\n但问何以云麻雀，日：“此妇年少佳人，又穿孝服，以意解之，为麻\n雀云。”\n哭\n一日，有罪犯同解子至门求卜，曾闻御史磨墨之说，亦取砚\n磨之，手重气粗，砚翻墨泼。龙曰：“不消磨矣，此乌台重犯也。”问\n能生否，日：“虽不遽死，一身重罪，铁案难翻。”罪犯哭曰：“某时\n运若此，何用生力？”龙曰：“据此，当迟七年，逢戌遇吕姓官人号\n冤，可改军罪，丑年可回。盖哭字双口为吕，下有犬字为戌，運字\n为军，用字为川，罪字为四川，生者有丑字形也。”\n龙有徒，河南人，欲辞归，谓龙曰：“明日有一宗财物，乞\n师助弟盘缠。”龙问其故，徒日：“适计行装，虑无盘费，偶见\n字\n触\n墙东缺月高升，知有盗者送"
