   "content": "【字触·字触·OCR第11/19节】（公有领域原典·清周亮工·测字）\n\n杨\n修\n人饱酪，魏武啖少许，盖上题一“合”字。杨修便啖日：“公教\n人啖一-口也。”修又尝过曹娥碑，见碑阴上题“黄绢幼妇外孙商\n臼”八字。魏武谓修曰：“解否？”日：“解。”魏武曰：“卿勿言，待吾\n思之。”行三十里，乃日：“吾已得。”令修别记所知。修曰：“黄绢，\n色丝也，于字为绝。幼妇，少女也，于字为妙。外孙，女之子也，于\n字内好。童白，受辛之器也，于字为辞。所谓“绝妙好辞’也。”魏\n武亦记之，与修同，叹目：“我才不及卿，乃三十里。”\n活\n杨德祖为魏武主簿，时作相国门，始构榱桷，魏武自出看，使\n人题门作“活”字，便去。杨见，即令坏之。既竟，曰：“门中活，阔\n字，王正嫌门大也。”\n宇\n触\n丕\n阐泽，字德润，拜侍中。初魏文帝即位，权问群臣日：“曹丕以\n盛年即位，恐孤不能及之，诸卿以为何如？”群臣未对，泽曰：“不\n及十年，丕其没矣，大王勿忧也。”权曰：“何以知之？”泽日：“以字\n言之，不十为丕，此其数矣。”文帝果七年而崩。《吴志》\n著来屐\n南齐世祖，梦著来屐行太极殿上。庾温曰：“展者，运应木也。\n又来字四子二点。”世祖年过此，即帝位。\n马上郎\n梁末，有“不见马上郎”之谣。及王僧辩灭，识者调马上郎，王\n字也。《《南史》）\n］\n与上人\n梁武帝除刘显国子博士。时有沙门讼田，帝书曰：“貞。”有司\n未辨，遍问莫知。显日：“贞字文为与上人。”帝因忌其能，出之。\n（《五代史》）\n侯\n景\n侯景尝谓人曰：“侯字人边作主，不作人，此明是人主也。”台\n城既陷，梁武帝尝语人曰：“侯景必得为帝，但不久耳。破‘侯景’\n字，成‘小人百日天子’，为帝当得百日。”按景以辛未年十一月十\n九日篡位，壬申年三月十九日败，得一百二十日；而景以三月一\n日便往姑孰，计在宫殿足满百日，其言竟验。（《南史》）\n天\n保\n齐文宣帝改年为天保，士有深识者日：“•天保’"
