   "content": "【字触·字触·OCR第19/19节】（公有领域原典·清周亮工·测字）\n\n牵附，学者承风，不胜其凿。姑以犇粗二字言之。牛体壮于鹿，鹿\n之行速于牛，今积三为字，而其义皆反之，何也？”公无以答。《《桯\n史》\n宋文帝好忌讳，改“骗”字，为马边瓜，以骗字似祸故也。（《本\n传》）\n崇\n宁\n崇甯钱上，蔡京书“崇”字，自山字中一笔下，甯字去心，当时\n有“有意破宋，无心宁国”之谣。（《贵耳集》）\n波涛（马守懸事）\n有江宁生者，客浔，闻马异，往看，不告姓名。值案头积书，指\n“波涛”二字日：“君能为一测否？”马谛视久，忽诧曰：“君佳士，何\n落节到此？夫水，《易》为坎，《范》为润下，陷不出，下不返，淫污漂\n溺，都从此生，君无还年矣！非噬非剥，肤沦于泽，是维女子，媾男\n为慝。夫不祥，其孰章氓之。冯戎，寿为大期，著田成畴，著金成\n铸，著人成俦。今也不然，并田为川，铸非其器，无人铸之，荡荡汨\n汨，靡所止期。循声日逃，巫臣窃妻子，意者其似之。”生傲然日：\n“君亦知仆何姓乎？”马曰：“象面既昭，群鬼夜器，吹律知姓，万物\n同忧。沄焉水区，寿谁其余。按象而谈，君非蔡仲之裔乎？”江宁\n生乃前谢日：“神哉先生！仆少失父兄，好为冶游，毕烬其官，携欢\n而东。我云彼龙，先生愍斯，维曷涂之从。”马曰：“夫凝虑者，不可\n惑以貌。知方者，不可淆以蹈。元冥失驱，后土其奠之。急之坤\n乡，无与巽谋。三寿作朋，西南得之，择里而安。安，钱唐其可迁\n乎？”其摘隐蹑秘，皆此类也。\n宇\n触\n•\n跋一\n沮诵制文，道因鸟迹；仓颉佐书，义次象形。盈其度，而日为\n君德；亏其旁，而月为臣规。措笔之间，已寓廋思于结体，而寄谐\n韵于缀墨矣。举一而言，凡百可触，故其行于世者，重之复之，累\n言而必畅其旨；其适于用者，敦之琢之，一言而能成其功。字之时\n义，大矣哉！触类而长，其一曰廈。盖两军相当，缪辞交遗；二豪\n骋辨，隐语为酬。自秦客廋词，而范子折其情；仲尼微言，"
