   "content": "【字触·字触·OCR第13/19节】（公有领域原典·清周亮工·测字）\n\n蔡茂初在广汉，梦坐太极殿，上有三穗禾，茂跳取之，得其中\n穗，辄复失之。以问郭贺，贺离席庆目：“大殿者，宫府之形象也。\n极而有禾，人臣之上禄也。取其中穗，是中台之位也。于字禾失\n为秧，虽曰失之，乃所以得秩也。”旬月而茂征焉，乃辟贺为掾。\n（《后汉书》）\n牛\n头\n蒋琬见推之后，夜梦有一牛头在门前，流血滂沱。意甚恶之，\n呼问占梦赵直。直目：“夫见血者，事分明也。牛角及鼻，‘公’字\n之象，君位必当至公，大吉之征也。”后琬官终大司马。（《蜀志》）\n何祗，字君肃。尝梦井中生来，以问占梦赵直。直曰：“非井\n中之物，会当移植。然来字四十下八，君寿恐不过此。 ”祇笑言：\n“得此足矣。”卒如所言。（《蜀志》）\n昱\n魏程昱本名立，少时梦上天两手捧日。太祖曰：“卿当为吾腹\n心。”乃于立上加日而为昱。\n点\n额\n吴王孙权尝梦北面顿首于天帝，忽见一人以笔点其额。举以\n问征士熊循，循曰：“吉祥矣，大王必为主。王者人之首，额者玉之\n上，王上加点，主字之象也。”《《吴祚国统》）\n梦生头角\n诸葛亮出北谷口，魏延为前锋。延梦头生角，以问占梦赵直。\n直诈日：“麒麟有角而不用，此不战而自附之象。”退而告人曰：\n“角之为字，刀下用也。头上用刀，其凶甚矣。”果为杨仪所杀。\n十八公\n丁固梦松生于腹上。松字十八公，后十八年为公。\n掷玉于门\n李盛作安南太守，梦人掷玉于门。盛目：“门加玉，国字也，必\n有荣闰。”果暴富贵。（《玉箱杂记》）\n字\n触\n宋\n桶\n宋桶梦内中有一人著赤衣，桶一手把两杖极打之。索统占\n日：“内中有人，是肉字也。两杖者，箸之象。极打者，饱肉食也。”\n三日过三寮，皆得肉食。（刘彦明《敦煌录》）\n走马上山\n郡主簿张宅梦走马上山，还绕舍二周，但见松柏，不知门处。\n索统占日：“马属火，火祸也。人上山为凶字。但见松柏，墓门象\n也。不知门处，无门也。三"
