   "content": "【字触·字触·OCR第16/19节】（公有领域原典·清周亮工·测字）\n\n宇\n触\n日\n王荆公戏作谜语：“画时圆，写时方，冬时短，夏时长。”吉甫\n解云：“东海有一鱼，无头又无尾，更除脊梁骨，便是两个谜。”\n贺\n资\n荆公字谜：“目字加两点，不作具字猜。贝字欠两点，不作目\n字猪。”（《钱氏私志》）\n图\n字\n荆公字谜：“四个口，尽皆方，十字在中央，不得作田字道，不\n得作器字商。”«《钱氏私志》）\n刘\n攽\n刘败与王安石最为故旧，王戏拆刘名曰，“刘敌不值分文。”\n刘亦拆王名目：“失女便成宕，无宀真是妬，下交乱真如，上头误\n当宁。”王大惭。又刘攽嘲王觌云：“汝何故见卖？”王日：“卖汝直。\n甚分文。”\n鸟\n鸠\n东坡闻荆公《字说》新成，戏曰：“以竹鞭马为笃，以竹鞭犬为\n何可笑？”荆公尝日：“鸠字以九以鸟，亦有征据否？”东坡日：\n术数金书中卷\n“《诗》云：‘鸬鸠在桑，其子七兮’和爹和娘，不是九个？”\n陈\n亚\n陈亚自为《亞字谜》日：“若教有口便哑，且要无心为恶。中间\n全没肝肠，外面任生棱角。”\n陈亚蔡襄\n陈少卿亚，维扬人，善诗，滑稽尤甚。尝与蔡君谟会于僧舍，\n君谟题诗屏间日：“陈亚有心终是恶。”亚即掌笔对曰；“蔡襄无口\n便成衰。”\n吕扩谢晖\n吕扩、谢晖亦以名相嚼。谢日：“无才终入广。”吕云：“不日便\n充军。”二人因而成隙。\n韩玉汝\n韩庄敏公缜求字于欧阳文忠公，公以小合幅纸书“玉女”二\n字送去，庄敏不乐。明日相见，犹有愠色。文忠公曰：“出处无点\n水也，君何径邪？”取笔添女三点水，相与一笑。盖《诗》中“玉女”，\n但音作汝也。前辈亦雅戏若此。\n宇触\n皛饭毳饭\n东坡尝与刘贡父言：“某与舍弟习制科时，日享三白，食之甚\n美，不复信世间有八珍也。”贡父问三白之说，坡言是一撮盐，一\n碟生萝卜，一碗饭，贡父大笑。久之，以简招坡吃皛饭。坡笑，不\n复省忆，谓人目：“贡父读书多，必有出处。”比至赴食，见案上所\n设，惟芦菔"
