   "content": "【字触·字触·OCR第17/19节】（公有领域原典·清周亮工·测字）\n\n月色大佳，石田行令云：“取上一字，下拆两字，字义相协。”倡云：\n“山上有明光，不知是日光月光。”文云：“堂上挂珠帘，不知是王\n家帘朱家帘。”陈云：“有客到館驿，不知官人舍人。”王云：“半夜\n生孩儿，不知是子时亥时。”各赏大觥。\n金元宾\n金元宾善诙诸。一日在文衡山内翰座，浪谑训蒙师潘某。潘\n愠曰：“吾有一对，尔能对，甘受尔悔。”金问之，日：“王大夫昆季\n筑墙，一土献三人之体。”金应声日：“潘先生父子沐发，番水湘两\n牛之头。”\n王文恪\n文恪公六七岁时，附学于舅氏。一小女使送茶，王戏以手握\n其手，舅氏出一对与对，日：“奴手为拏，此后莫拏奴手。”王对日：\n“人言是信，从今毋信人言。”\n李西涯\n焦阁老芳面黑而长如驴，尝谓西涯曰：“君善相，烦一看。”李\n久之乃曰：“左相像马尚书，右相像卢侍郎，必至此地位。”马与卢\n合，乃一驢字，始知其戏。\n.….：\n诸理斋\n凤林夏五，名景倩，延师周四维训子，以不称，欲再延。妻日：\n“何为又增人口？”夫不从，又延罗成吾。时诸理斋亦馆于夏，戏\n曰：“夏五本是五，增口便成吾。四维尚未去，如何又请羅？”\n玻\n杨孟平，四明人，居金陵，最善戏，能篆书。有靴匠号“东门王\n皮”者，骤富。作一室以延宾，求扁于孟平，孟平纂“阑玻”二字与\n之。或请之，孟平曰：“加一画，即东门王皮也。”\n一\n極\n东莞方彦脚俊善戏谑，又善拆宝作谜。如“上不在上，下不在\n下，不可在上，且宜在下”，谓“一”字也，“木了又一口，非杏亦非\n呆，勿作查字说，勿作困字猜。”谓“極”字也。\n宇\n触\n杜\n渭\n蜀人杜渭、江朝绅令麻城，居官执法，不敢干以私。一日宴乡\n绅，梅西野倡令要拆字，入俗语二句，梅云：“单奚也是奚，加点也\n是溪。除却溪边点，加鸟却鷄。俗语云：得志猫儿雄似虎，败翎\n鹦鹉不如鸡。”毛石崖云：“单青也是青，加点也是清，除却青边"
