   "content": "【字触·字触·OCR第6/19节】（公有领域原典·清周亮工·测字）\n\n羽客，无不接引。一日昼寝，有僧来谒，而 者不为通。翌日至，\n又如之。僧叹婉日：“吾以尔主好道，故来救其厄。今若此，信命\n也。”取笔题字数行于室东小庑而去。翌日立秋，其夜火发，宅产\n荡尽，独僧所题小庑无恙，阍者因具言所以。视其书日：“坐不得，\n行不得，愁无心，口添画，大口小口，青黄共色。”有解日：“坐不\n得，行不得，立也；愁无心，秋也；口添画，日也；大口，小口，回也；\n青黄共色，绿也，凡染绿者，必青与黄合也。乃立秋日回禄也。”\n（《居东集》）\n三人同一口，\n杨忠烈公进，少落拓，不肯习程文，诸生皆心薄之。彭幼朔独\n奇，以次必售。癸卵元旦试诸生，批文后云：“但得三人同一口，\n…⋯\n宇\n触\n九霄之上便飞腾。”连以是科乡荐•主考日孙如游、董复亨，房考\n日刘文琦，三人同口之征也。\n西\n瓜\n有一人以求嗣，诣何仙祈梦。梦人抱一西瓜相赠，又见半子\n于西瓜之外。圆者称贺云：“瓜最多子，行且见累累矣。”其人至老\n不得嗣，自以梦无验，语方大古。方笑日：“瓜露半子，公其孤乎？”\n始悟。\n卷二\n外部\n李\n嫔\n唐司空李蜈，始名虬。赴举之秋，偶自题名于屋壁。经宵忽\n睹名上添一划，乃成虱字矣。蜈曰：“虱者蟆也。”遂改名蟆。明年\n果登第。（《南楚新闻》）\n北\n千\n李暠叛，有书招杨德辉赴斋。有老道士崔无斁，自言患聋，有\n道而托算术，往往预知吉凶。德辉问曰：“将欲北行何如？”崔令划\n地作字。杨乃书“北干”两字。崔公以干插北，成“乖”字，去即乖\n耳。杨遂不果去，而李暠斋日就擒，道士多罹其祸。杨之幸免，由\n崔之力也。\n蟹\n曹翰，兴国四年从征幽州，率部攻城东南隅，卒掘土得蟹以\n献。翰谓诸将曰：“蟹，水物而陆居，失所也。且多足，彼援将至，\n不可进拔之象。况蟹者，解也，其班师乎？”已而果验。（本传）\n贝\n州\n庆历四年，贝州卒王则据城叛。诏明镐加讨，久无功"
