   "content": "【字触·字触·OCR第15/19节】（公有领域原典·清周亮工·测字）\n\n父母丧亡之变。\n皮\n石\n一人梦靴匠倚石，不知何意。占者日：“靴匠乃皮工也，皮旁\n石，破字也。”不久家破，萧条人口。\n榮\n一士梦一树端两焰并发，占者日：“木两火，榮耀之光。”果得\n登第。\n竄\n有一吏人追于官讼，祷梦于神。梦鼠头戴笠，既寤不解。因\n而再寐，梦神示日：“汝可质之某状元。”会有同祈梦者，本以功名\n事来祷，竟无梦。吏故不知其人之姓，偶以梦中始末语之。其人\n特异之，乃剖示曰：“鼠头戴笠，竄字也。亟走匿为是。”某状元即\n指是人也，后果大魁。\n白\n日一角，白字也。角者，冠翅也，文人梦之，白屋书生头角峥\n嵘之象。\n•\n玉\n土山横一剑，玉字也。梦者佩玉之兆也。女人梦之，主产大\n贵之子。\n鳏\n一人幼时，常梦沼中四鱼，占者曰：“一水四鱼，鳏字也。”是\n人至老孤独。\n失\n一人梦骑牛背，占曰：“人在牛背，失字也。”果遭失脱之忧。\n狱\n一人梦一人言，一犬吠。术士曰：“人言犬吠，乃狱字也。”果\n遭狱囚之系。\n宇\n触\n斗\n门\n一人梦一斗入门，占日：“一斗入门，斗也。”是日果有斗殴之\n恐。\n卷五\n谐部\n东方朔\n汉武帝尝以隐语召东方朔。时上林献枣，帝以杖击未央前殿\n摇曰：“叱叱，先生東束。”朔至，日：“上林献枣四十九校乎？溯见\n上以杖击楹为两木，两木，林也。束束，枣也。叱叱，四十九也。”\n（《本传》）\n薛\n综\n蜀使张奉于孙权前嘲尚书阚泽姓名，泽不能答。薛综下行\n酒，因目：“蜀有何也？有犬日獨，无犬为蜀。横目苟身，虫入其\n腹。”奉日：“不当复列君吴邪？”综应声曰：“无口为天，有口为吴。\n君临万邦，天子之都。”奉无以对。《《启颜录》）\n氏\n是仪，字子羽，北海营陵人，本姓氏。初为县吏，后仕郡。郡\n相孔融嘲仪，言：“氏字，民无上。可改为是。”乃遂改焉。《《吴志》）\n鳳\n嵇康与吕安善，每一相思，千里命驾。安复来，值康不在。喜\n出户延之"
