   "content": "【字触·字触·OCR第1/19节】（公有领域原典·清周亮工·测字）\n\n入（425）孕（425）田（426）呆（426）脚（426）觚不觚，觚哉，\n觚哉（426）王日叟（426） 二（427）月（427）彭（427）易（427）\n赏（427）秦字诗（427）沈筠溪（428）蒋涛（428）棗棘（428）\n十干名（428）田（428）肅（429）巧对（429）\n卷六，\n说部•\n（430）\n董彦远（430）人字具五形（430）无（431）聋字从龙（431）\n罚（431）對（431）叠（431）智慧（432）心火（432）水（432）\n辰（432）日百（432）仁義（433）贱（433）疾病（433）病（433）\n地（433）黍（434）1L（434）同田分贝（434）富自田起（434）\n随.（434）吊（435）闪（435）革圭（435）女子（435）火伴（436）\n止戈（436）反正为乏（436）郡县（436）犇粗（437） （437）\n崇宁（437）波涛（437）\n跋一。\n跋二\n跋三\n（439）\n（440）\n（440）\n字\n触\n序一\n六书之学，莫妙于会意。会意之妙，在合众体以成文，如止戈\n为武、力田为男、背私为公、一勺为与、十口为古、大可为奇之类。\n此二体合也。盥字从水从皿，指事；从白而取之，会意。廛字从广\n从里，指事；从土而分之，会意。亟字从二，象天地形，从人从口从\n又，谓人在天地间，口谋之，手之，时不可失，会意。暴字从同，\n象甗形，从一象突形，一人两手安甗于其上，而又一人两手，析薪\n投之火中，会意则合三体以至六体。其字甚多，不可胜数。夫小\n篆变自李斯，说文肪于许慎，当时遂有此说，已开后人离合相字\n之门矣。故蔡邕之“黄娟幼妇”，孔融之“進父屈节”，魏武之“人一\n口”，梁武之“与上人”，王浚之“三刀”，丁固之“十八公”，皆从此\n出。至谢石、胡宏之徒，直以此技为占卜，则变化其意而"
