   "content": "【字触·字触·OCR第5/19节】（公有领域原典·清周亮工·测字）\n\n也。光业见《吴越备史》颇详。师鲁文章传世，且刚直有守，\n非欺后世者，可信不疑也。又按：“唐浔阳簿刘肃所著《唐世\n语林》已明载“皮日休，黄巢时遇害，其子仕钱镙”矣。\n草重生\n初，董昌未败前，狂人于越州旗亭客舍题诗四句云：“日日草\n重生，悠悠傍素城。诸侯逐白兔，夏满镜湖平。”初人不晓其词，及\n昌败，方悟。草重，董字，日日，昌字。素城，越城，隋越国公杨素\n所筑也。诸侯者，猴乃钱，申生属也；白兔，昌，卵生属也。夏满，\n六月也；镜湖，越中也。（《会稽录》）\n吕洞宾\n吕洞宾谓侯生日：“蛇蝎，天地淘以自然之气，使之生以遂\n性，杀此救彼，有损无益。”取纸隐语：“三口共一室，室畔水边\n清。”乃吕洞宾字。\n许碑重立\n汉，太尉许馘碑，久磨灭。诸孙再刻之，题八字碑阴日：“谈马\n砺毕，主田数七。”人莫能晓。徐铉父延休，一见解曰：“谈马许字，\n砺毕碑字，主田重字，数七立字。”\n三梦\n段思平生有异兆，蒙主杨于真忌之，使人索捕，思平逃匿。饥\n摘野桃剖之，核肤有文日：“青昔。”思拆之日：“青乃十二月，昔乃\n二十一日。今杨氏政乱，吾当以是日举义乎？”遂起兵，方至河干。\n是夕，思平梦人斩其首，又梦玉筑耳阙，又梦镜破，惧不敢进兵。\n其军师董迦罗曰：“三梦皆吉兆也！公为大夫，夫去首，为天，天子\n兆也。玉鹹去耳，为王之兆也。镜中有影，如人有敌，镜破则无影，\n无影则无敌矣。三梦皆吉兆也。”思平乃决。明且，遂引兵渡江，\n逐杨氏而有蒙国，遂改国号日“大理”。时晋天福二年也。（《淇\n记》\n•\n王\n溥\n后汉王溥，家贫，穿井得铁印，铭曰：“佣力得富至亿庾，一土\n三田军门主。”溥以亿钱输官，得中垒校尉。三田一土，壘字。校\n尉掌北军垒门，故目军门主。（《拾遗录》）\n石笋隐字\n成都子城西金容坊，有石二株，挺然耸峭，高丈余。《耆旧\n传》云：“其名有六，日石笋，日蜀妃坟"
