   "content": "【字触·字触·OCR第9/19节】（公有领域原典·清周亮工·测字）\n\n争字是解元头，中七人，城内五人，城外二人。”已而果然。或问\n故，日：“测此字时，偶念及小学‘天子争臣七人，诸侯争臣五人。’\n城内候地，故五人；城外远于京师，故二人，以远于京师北直，故\n不言七人，止合城内为七也。”\n字\n触\n子\n有以“子”字问六甲者，栎公日：“一个丫头，非女而何？”果\n验。\n徒\n冯公失厮养儿，书“走”字于仆掌上，视栎公。时一仆同至，公\n曰：“双人加走为徒字，觅之徒然耳。然是人更不须觅，不久即亡，\n以走字离合之，为土下人也。”后日见厮养儿死大堤下。\n携\n一士人小试，写一“携”字问之。日：“君问试事，必不如意。盖\n携字进不成进（進），秀不成秀，才不成才也。”后果然。\n幾\n谢楠公，有传其子以下第愤激披剃者。谢忧甚，书“幾”字视\n栎公。公曰：“丝在人首，发也。旁著一戈，剃发必矣。”后果验。\n（《顾曲亭纪闻》）\n闵\n闵君母病，即以姓视标公。公日：“以文临门，非吊即庆。病\n者在榻，无他庆事，吊当至矣。况字有门内女不成之象，恐不能起\n矣。”越数日验。《《顾曲亭纪闻》）\n今\n有以“今“字问六甲煮，栎公曰：“此人一丁也，必生男。”问何\n日，曰：“逢「始生，在念日，盖有念字头也。”问平安否，日：“目今\n夏日火旺，人在丁上，正乘旺地，主子母俱平安。”\n非\n翠\n邑有大猾周体乾者，令公欲除之，以“非”字视栎公，公日：\n“乾之左右，无不相逼者，除之必矣。”既下狱，令公复指环翠楼\n“苯”字视公，公曰：“字上二乾，皆以笔直之。左视乾卒，右视乾\n卒，乾不水矣。”后为抚军扑杀。（《顾曲亭纪闻》）\n串\n字\n有叩试事者，书“串”字，术者日：“不特乡得隽，南官亦应\n高捷。盖以串寓二中字也。”一生在傍，亦书一“串“字令观。术者\n曰：“君不独不与宾兴，更有疾。”询其所以，日：“彼以无心书，故\n当尔字。君以有心书，早下加心，乃患字耳。”已"
