   "content": "【字触·字触·OCR第2/19节】（公有领域原典·清周亮工·测字）\n\n宗，观象以知文，感幽以著说，而吉凶祸福，居然不爽者。《易》日：\n“知几其神，通其道者。”无字中，忽示以字矣。作几部第四。\n谐部\n庄述齐谐，惟取志径；晏名讽谏，半杂诙谐。斯虽劈字以成\n章，岂非滑稽之巧笑，俳优所一视者乎？然方言俚俗而辞文，风刺\n刻深而旨雅。絜之离合之篇，固有正变之异；揆之风雅之则，亦仅\n诗曲之分。巧成杼轴，取办俄顷，可以发人慧，可以广人思。深其\n义类，要以推测之佐也，岂独风趣绝人而已哉？作谐部第五。\n说部\n观乎说，几乎六书之义焉。淳于绝缨之后，进以庄言；长卿侈\n丽之余，归之正则。是以曲终雅奏也，故受之以说部终焉。然问\n字不啻万干，说文亦多纷赜。他若安石之陈编，则天之创体，如斯\n等类，不可胜收，而仅有取乎此者，非离合之义弗载焉耳。\n顺治丁亥嘉平望后二日，栎下老人\n识于樵川之诗话楼\n字\n触\n卷一廋部\n：；\n《越绝书》\n《越绝书》云：“以去为姓，得衣乃成。厥名有米，覆之以庚。禹\n来东征，死葬其乡。不直自斥，托类自明。”又：“文属词定，自于邦\n贤。以口为姓，承之以天。楚相屈原，与之同名。”（杨用修日：“去\n得衣，乃袁字。米覆庚，乃康字。禹葬会稽，是会稽人袁康也。其\n•不直自斥，托类自明’，颗旨昭然，欲后人知也。‘文属词定，自于\n邦贤’，言共著非康一人也。以口承天，吴字；屈原同名，平字；与\n康同著此书者，乃吴平也。”或曰：“二人何时人也？”日：“东汉\n也。”东汉之末，文人好为隐语，黄绢其著者也。孔融隐其姓名于\n《离合》诗，魏伯阳隐其姓于《参同契》。融与伯阳俱汉末时人，故\n字稍同。则兹书之著为同时，何疑焉？）\n《参同契》\n《参同契•后序》云：“郐会鄙夫，幽谷朽生。委时去害，依托\n丘山。循游寥廓，与鬼为邻。百世一下，遨游人间。汤遭厄际，水\n早隔屏。”隐“会稽魏伯阳”五字。古魏字作费，故云丘山。\n藁\n砧\n古"
