   "content": "【字触·字触·OCR第12/19节】（公有领域原典·清周亮工·测字）\n\n状元。于“臀无肤”，得丁未探花。盖字文臀即展也，臀谐其声，乃\n以无肤去肉，为殿头之祥，而以卦爻第三，知其名次。此其析字法\n也。\n奇\n《草木子》：贾似道有异志。一术士能析字，贾以策画地作\n“奇”字，术日：“相公之志不谐矣！道立又不可，道可又不立。”贾\n字\n触\n默然，求其罪而遣之。恐泄其事，使人害诸途。\n相\n元相哥丞相，元名来哥。拜相后，延术者书“来”字令测，日：\n“今已作相，但欲知相位日月久近？”日：“木字十八字也，上有三\n个十字，在相位当有四十八个月。”来哥不满，遂更名相哥。复书\n“相”字令测，日：“‘目’字横看，又是四字，若是，则横直只四十八\n个月。”至元辛卵正月败，其言果验。\n豐‹张乘槎事）\n刘命熙祖父，居越有疾。刘在钱塘，延槎，写一“豐”字，令占\n之。槎日：“死矣！尚何占焉？”是晚音果至。异日印其故，槎日：\n“豐字之形，山者，墓所也；二丰者，墓上木也；豆者，祭器也。解兆\n如此，庸非死乎？”\n德\n刘常心有所欲占，延槎而不言其事，试令付之，以验其术。槎\n日：“书一字方可占。”适有小学生在旁，正写习《干字文》至“德建\n名立”。刘就指“德”字令占之。槎目：“子欲占行人耳。”刘日：“然。\n何时当至？”槎日：“自今十四日必来。”刘日：“恐事未了，不肯\n来。”槎曰：“一心要来。”后果如所占。刘问故，槎曰：“德字双立\n人，乃行人耳，故知占行人。旁有十四字头，故云十四日。下又一\n心字形，所以云一心要来也。”\n陋\n柳道彦，性迁缓而好思，尝在旋舍，奴子盗其金亡去。资斧缺\n甚，乘款段行。兀兀梦人画“随”字视之，思：“陋旁抱耳，乃是人字\n转手入怀，物尚不失。”行行忽见一肆所卖饼面，因思：“饼面者，\n丙𠃊也，于陋字始全。其在是乎？”下马入其室，果得奴子，而金尚\n在怀。《《耳谈》）\n骀\n大梁二岑马公，为长山令，厚遇青衿王君。王"
