   "content": "【字触·字触·OCR第3/19节】（公有领域原典·清周亮工·测字）\n\n猛同谒在坐，目：“木上破天，未字也。公未可妄动。”敦不听，以至\n于败。\n宇触\n剡\n《道经》云：“两火一刀可以逃。”言剡中名山，可以避灾也。故\n汉晋以来，多隐逸之士，括州天姥是其处。（《会稽集》）\n王\n恭\n王恭在京口，民间谣云：“黄头小人欲作贼，阿公在城下指缚\n得。”又云：“黄头小人欲作乱。赖得金刀作蕃扦。”黄字上，恭字头\n也；小人，恭字下也；金刀，刘也。寻如谣言。\n桓灵宝\n东晋桓灵宝时，朱雀门下，忽有两小儿通身如墨，相和作《芒\n龙歌》。路边小儿，从而和之数十人。歌云：“芒龙首，绳缚腹，车\n无轴，倚孤木。”声甚哀楚，听者亡归。日既夕，二小儿还入建康，\n至阁下，遂成一双漆鼓槌。鼓吏列云：“槌积久，此恒失之而复得，\n不意作人也。”明年春，而灵宝败。言“车无轴，倚孤木”，“桓”字\n也。荆州送灵宝首，用败笼，因包裹之，又以芒绳缚其尸，沉诸江\n中，悉如童谣所言。\n冯\n昌\n晋符融，尝为司隶校尉。京兆人董丰，游学三年而返，过宿妻\n家。是夜妻为贼所杀，妻兄疑丰杀之，送于有司。丰不堪楚掠，自\n诬。融察而异之，问日：“汝行往返，颇有径异及卜筮否？”丰曰：\n“初将发，夜梦乘马南渡水，返而北渡，复自北而南，马停水中，鞭\n策不去，俯而视之，见两日在于水上，马左白而湿，右干而燥。寤\n而心悸，窃以为不样。还之夜，复梦如初。问之筮者，筮曰：‘忧狱\n讼，远三枕，避三沐。’既至，妻为具淋，夜授丰枕。丰记筮者之言，\n皆不从，既乃自沐，枕枕而寝。”融日：“吾知之矣！”马左而湿，湿，\n水也。左水右马，冯字也。两日，昌字也。其为冯昌乎？”于是推\n检，获昌而诘之，具首服日：“本与其妻谋杀董丰，期以新沐枕枕\n为验，是以误中妇人。”（本传）\n按：《拊掌录》所载，事与此相类，附录之：\n西川费孝先，善轨革，世皆知名。有客人王旻，因集货至\n成都，求卦。孝先目：“"
